  { id: 268, en: "dot", zh: "點", kk: "[dɑt]", pos: "n.", cat: "色彩與形狀 🎨", ex: "Draw a small red dot in the middle.", ex_zh: "在正中央點上一個紅色的小圓點。" },
  { id: 269, en: "down", zh: "向下", kk: "[daʊn]", pos: "prep./adv.", cat: "方向與位置 📍", ex: "Walk down the stairs carefully.", ex_zh: "小心地走下樓梯。" },
  { id: 270, en: "dozen", zh: "一打(12個)", kk: "[ˈdʌzən]", pos: "n.", cat: "數量與代名詞 🔢", ex: "Mom bought a dozen eggs for baking.", ex_zh: "媽媽買了一打雞蛋準備做烘焙。" },
  { id: 271, en: "dragon", zh: "龍", kk: "[ˈdræɡən]", pos: "n.", cat: "動物與自然 🐶", ex: "We watch exciting dragon boat races.", ex_zh: "我們觀看精彩刺激的端午划龍舟比賽。" },
  { id: 272, en: "draw", zh: "畫", kk: "[drɔ]", pos: "v.", cat: "學校與學習 📚", ex: "Use colored pencils to draw trees.", ex_zh: "用彩色鉛筆畫出綠油油的樹木。" },
  { id: 273, en: "drawer", zh: "抽屜", kk: "[ˈdrɔɚ]", pos: "n.", cat: "日常用品 🎒", ex: "Keep your rulers inside the desk drawer.", ex_zh: "把你的尺收進書桌的抽屜裡。" },
  { id: 274, en: "dream", zh: "做夢/夢想", kk: "[drim]", pos: "v./n.", cat: "動作與思考 🧠", ex: "I have a dream to be a brave pilot.", ex_zh: "我的夢想是成為一名勇敢的飛行員。" },
  { id: 275, en: "dress", zh: "洋裝/穿著", kk: "[drɛs]", pos: "n./v.", cat: "衣著與配件 👕", ex: "She wears a pretty yellow dress today.", ex_zh: "她今天穿了一件漂亮的黃色洋裝。" },
  { id: 276, en: "drink", zh: "喝/飲料", kk: "[drɪŋk]", pos: "v./n.", cat: "食物與飲品 🍕", ex: "Drink more fresh water every day.", ex_zh: "每天要多喝乾淨新鮮的白開水。" },
  { id: 277, en: "drive", zh: "駕駛/開車", kk: "[draɪv]", pos: "v.", cat: "動作與活動 🏃", ex: "Dad drives safely when we travel.", ex_zh: "我們出門旅行時爸爸開車都很安全。" },
  { id: 278, en: "driver", zh: "駕駛者/司機", kk: "[ˈdraɪvɚ]", pos: "n.", cat: "人物與角色 👥", ex: "Say thank you to the bus driver.", ex_zh: "下車時記得跟公車司機說聲謝謝。" },
  { id: 279, en: "drop", zh: "掉落/一滴", kk: "[drɑp]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Be careful not to drop the glass cup.", ex_zh: "小心不要把玻璃杯摔落在地上。" },
  { id: 280, en: "drum", zh: "鼓", kk: "[drʌm]", pos: "n.", cat: "學校與學習 📚", ex: "He beats the big drum with energy.", ex_zh: "他充滿活力地敲擊著大鼓。" },
  { id: 281, en: "dry", zh: "乾的/擦乾", kk: "[draɪ]", pos: "adj./v.", cat: "情緒與特質 😊", ex: "Dry your hands with a clean towel.", ex_zh: "用乾淨的毛巾把雙手擦乾。" },
  { id: 282, en: "duck", zh: "鴨", kk: "[dʌk]", pos: "n.", cat: "動物與自然 🐶", ex: "Yellow ducklings swim across the pond.", ex_zh: "黃色小鴨排隊游過了池塘。" },
  { id: 283, en: "dumpling", zh: "湯圓/水餃", kk: "[ˈdʌmplɪŋ]", pos: "n.", cat: "食物與飲品 🍕", ex: "Pork dumplings taste juicy and delicious.", ex_zh: "豬肉水餃吃起來多汁又美味。" },
  { id: 284, en: "during", zh: "在…期間", kk: "[ˈdjʊrɪŋ]", pos: "prep.", cat: "時間與日常 ⏰", ex: "Listen carefully during class time.", ex_zh: "上課期間要專心聽講。" },
  { id: 285, en: "each", zh: "每一", kk: "[itʃ]", pos: "adj./pron.", cat: "數量與代名詞 🔢", ex: "Each child receives a nice small gift.", ex_zh: "每個小朋友都拿到了一份精緻的小禮物。" },
  { id: 286, en: "ear", zh: "耳朵", kk: "[ɪr]", pos: "n.", cat: "身體與健康 🦵", ex: "Rabbits have very long and soft ears.", ex_zh: "兔子長著一對又長又柔軟的耳朵。" },
  { id: 287, en: "early", zh: "早的", kk: "[ˈɝli]", pos: "adj./adv.", cat: "時間與日常 ⏰", ex: "Wake up early and you won't be late.", ex_zh: "早點起床上學就不會遲到囉。" },
  { id: 288, en: "earth", zh: "地球/泥土", kk: "[ɝθ]", pos: "n.", cat: "動物與自然 🐶", ex: "We all live together on planet Earth.", ex_zh: "我們大家共同生活在美麗的地球上。" },
  { id: 289, en: "east", zh: "東方", kk: "[ist]", pos: "n./adj.", cat: "方向與位置 📍", ex: "The bright sun rises from the east.", ex_zh: "耀眼的太陽從東方緩緩升起。" },
  { id: 290, en: "Easter", zh: "復活節", kk: "[ˈistɚ]", pos: "n.", cat: "時間與日常 ⏰", ex: "Kids search for painted eggs on Easter.", ex_zh: "復活節時小朋友會在草地上尋找彩蛋。" },
  { id: 291, en: "easy", zh: "容易的", kk: "[ˈizi]", pos: "adj.", cat: "情緒與特質 😊", ex: "This spelling game is fun and easy.", ex_zh: "這個拼字遊戲既有趣又很容易上手。" },
  { id: 292, en: "eat", zh: "吃", kk: "[it]", pos: "v.", cat: "動作與活動 🏃", ex: "Eat fresh fruit to keep your body fit.", ex_zh: "多吃新鮮水果保持身體健康。" },
  { id: 293, en: "egg", zh: "蛋", kk: "[ɛɡ]", pos: "n.", cat: "食物與飲品 🍕", ex: "Birds lay small spotted eggs in the nest.", ex_zh: "鳥兒在巢裡下了小小的斑點蛋。" },
  { id: 294, en: "eight", zh: "八", kk: "[et]", pos: "num.", cat: "數量與代名詞 🔢", ex: "An octopus has eight long arms.", ex_zh: "章魚總共有八隻長長的觸手。" },
  { id: 295, en: "eighteen", zh: "十八", kk: "[ˌeˈtin]", pos: "num.", cat: "數量與代名詞 🔢", ex: "There are eighteen desks in our room.", ex_zh: "我們教室裡整齊擺放著十八張課桌。" },
  { id: 296, en: "eighth", zh: "第八", kk: "[etθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "August is the eighth month of the year.", ex_zh: "八月是一年當中的第八個月份。" },
  { id: 297, en: "eighty", zh: "八十", kk: "[ˈeti]", pos: "num.", cat: "數量與代名詞 🔢", ex: "My grandfather is eighty years old.", ex_zh: "我的爺爺今年剛好八十歲。" },
  { id: 298, en: "either", zh: "也不/任一", kk: "[ˈiðɚ]", pos: "adv./adj.", cat: "日常表達 💬", ex: "I don't like bitter coffee either.", ex_zh: "我也很不喜歡苦澀的黑咖啡。" },
  { id: 299, en: "elementary school", zh: "小學", kk: "[ˌɛləˈmɛntri skul]", pos: "n.", cat: "學校與學習 📚", ex: "We study happily in elementary school.", ex_zh: "我們在小學校園裡快樂地學習成長。" },
  { id: 300, en: "elephant", zh: "大象", kk: "[ˈɛləfənt]", pos: "n.", cat: "動物與自然 🐶", ex: "The elephant sprays water with its long nose.", ex_zh: "大象用牠長長的大鼻子向空中噴水。" }
