  { id: 301, en: "eleven", zh: "十一", kk: "[ɪˈlɛvən]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Soccer teams have eleven players on the field.", ex_zh: "一隊足球隊在場上有十一名球員。" },
  { id: 302, en: "eleventh", zh: "第十一", kk: "[ɪˈlɛvənθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "November is the eleventh month of the year.", ex_zh: "十一月是一年之中的第十一個月份。" },
  { id: 303, en: "else", zh: "其他的", kk: "[ɛls]", pos: "adv./adj.", cat: "日常表達 💬", ex: "Would you like anything else to eat?", ex_zh: "你還想要吃點其他什麼東西嗎？" },
  { id: 304, en: "e-mail", zh: "電子郵件", kk: "[ˈiˌmel]", pos: "n./v.", cat: "社會與生活 🏢", ex: "Send an e-mail to your teacher.", ex_zh: "寄一封電子郵件給你的老師。" },
  { id: 305, en: "end", zh: "結束", kk: "[ɛnd]", pos: "v./n.", cat: "時間與日常 ⏰", ex: "The movie comes to a happy end.", ex_zh: "這部電影迎來了幸福美滿的結局。" },
  { id: 306, en: "engineer", zh: "工程師", kk: "[ˌɛndʒəˈnɪr]", pos: "n.", cat: "人物與角色 👥", ex: "An engineer designs strong tall bridges.", ex_zh: "工程師設計出堅固又高大的橋樑。" },
  { id: 307, en: "English", zh: "英語", kk: "[ˈɪŋɡlɪʃ]", pos: "n./adj.", cat: "學校與學習 📚", ex: "We practice speaking English every day.", ex_zh: "我們每天都開口練習說英語。" },
  { id: 308, en: "enjoy", zh: "喜愛/享受", kk: "[ɪnˈdʒɔɪ]", pos: "v.", cat: "情緒與特質 😊", ex: "I enjoy reading exciting story books.", ex_zh: "我非常享受閱讀精彩的故事書。" },
  { id: 309, en: "enough", zh: "足夠的", kk: "[ɪˈnʌf]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "Get enough sleep to stay energetic.", ex_zh: "要有充足的睡眠才能保持滿滿活力。" },
  { id: 310, en: "enter", zh: "進入", kk: "[ˈɛntɚ]", pos: "v.", cat: "動作與活動 🏃", ex: "Knock before you enter the classroom.", ex_zh: "走進教室之前請先記得敲門。" },
  { id: 311, en: "envelope", zh: "信封", kk: "[ˈɛnvəˌlop]", pos: "n.", cat: "日常用品 🎒", ex: "Put your card inside the envelope.", ex_zh: "把親手寫的卡片放進信封裡。" },
  { id: 312, en: "eraser", zh: "橡皮擦", kk: "[ɪˈresɚ]", pos: "n.", cat: "學校與學習 📚", ex: "Lend me your eraser for a minute, please.", ex_zh: "請借我用一下你的橡皮擦好嗎？" },
  { id: 313, en: "eve", zh: "前夕", kk: "[iv]", pos: "n.", cat: "時間與日常 ⏰", ex: "We get together on New Year's Eve.", ex_zh: "我們在除夕夜全家團聚在一起。" },
  { id: 314, en: "even", zh: "甚至/平坦的", kk: "[ˈivən]", pos: "adv./adj.", cat: "日常表達 💬", ex: "He can even speak three languages.", ex_zh: "他甚至能流利地說三種不同語言。" },
  { id: 315, en: "evening", zh: "傍晚", kk: "[ˈivnɪŋ]", pos: "n.", cat: "時間與日常 ⏰", ex: "We take a breezy walk in the evening.", ex_zh: "我們傍晚時在涼風中散散步。" },
  { id: 316, en: "ever", zh: "曾經", kk: "[ˈɛvɚ]", pos: "adv.", cat: "日常表達 💬", ex: "Have you ever seen a flying squirrel?", ex_zh: "你曾經親眼看過會飛的飛鼠嗎？" },
  { id: 317, en: "every", zh: "每一個", kk: "[ˈɛvri]", pos: "adj.", cat: "數量與代名詞 🔢", ex: "We learn five new words every day.", ex_zh: "我們每天都要認識五個新單字。" },
  { id: 318, en: "everyone", zh: "每一個人", kk: "[ˈɛvriˌwʌn]", pos: "pron.", cat: "人物與角色 👥", ex: "Everyone in our class loves sports.", ex_zh: "我們班上的每一個人都很熱愛運動。" },
  { id: 319, en: "everything", zh: "每件事", kk: "[ˈɛvriˌθɪŋ]", pos: "pron.", cat: "日常表達 💬", ex: "Everything is ready for the school trip.", ex_zh: "校外教學的所有東西都準備妥當了。" },
  { id: 320, en: "example", zh: "例子", kk: "[ɪɡˈzæmpəl]", pos: "n.", cat: "學校與學習 📚", ex: "Teacher gave us a very clear example.", ex_zh: "老師給了我們一個非常清楚易懂的例子。" },
  { id: 321, en: "excellent", zh: "極好的/優秀的", kk: "[ˈɛksələnt]", pos: "adj.", cat: "情緒與特質 😊", ex: "You did an excellent job on the test.", ex_zh: "你這次考試表現得真是太優秀了！" },
  { id: 322, en: "except", zh: "除了……之外", kk: "[ɪkˈsɛpt]", pos: "prep.", cat: "日常表達 💬", ex: "Everyone is here except Tom.", ex_zh: "除了湯姆之外，大家都已經到齊了。" },
  { id: 323, en: "excited", zh: "感到興奮的", kk: "[ɪkˈsaɪtɪd]", pos: "adj.", cat: "情緒與特質 😊", ex: "Kids felt excited about the camping trip.", ex_zh: "小朋友們對這次露營活動感到非常興奮。" },
  { id: 324, en: "exciting", zh: "令人興奮的", kk: "[ɪkˈsaɪtɪŋ]", pos: "adj.", cat: "情緒與特質 😊", ex: "The dodge ball game was so exciting.", ex_zh: "那場躲避球比賽真是令人熱血沸騰。" },
  { id: 325, en: "excuse", zh: "原諒/藉口", kk: "[ɪkˈskjuz]", pos: "v./n.", cat: "日常表達 💬", ex: "Excuse me, where is the music room?", ex_zh: "不好意思，請問音樂教室在哪裡呢？" },
  { id: 326, en: "exercise", zh: "運動/練習", kk: "[ˈɛksɚˌsaɪz]", pos: "v./n.", cat: "體育與運動 🏅", ex: "Daily exercise keeps our bodies fit.", ex_zh: "天天運動能維持身體健康有活力。" },
  { id: 327, en: "expensive", zh: "昂貴的", kk: "[ɪkˈspɛnsɪv]", pos: "adj.", cat: "日常表達 💬", ex: "This new bike is too expensive.", ex_zh: "這輛全新的腳踏車實在太昂貴了。" },
  { id: 328, en: "experience", zh: "經驗", kk: "[ɪkˈspɪriəns]", pos: "n./v.", cat: "動作與思考 🧠", ex: "Camping in the wild is a wonderful experience.", ex_zh: "在野外露營是一次美好的成長經驗。" },
  { id: 329, en: "eye", zh: "眼睛", kk: "[aɪ]", pos: "n.", cat: "身體與健康 🦵", ex: "Protect your eyes when reading books.", ex_zh: "看書時要好好保護自己的眼睛。" },
  { id: 330, en: "face", zh: "臉孔/面對", kk: "[fes]", pos: "n./v.", cat: "身體與健康 🦵", ex: "Wash your face with warm water.", ex_zh: "用溫暖的清水把小臉蛋洗乾淨。" },
  { id: 331, en: "fact", zh: "事實", kk: "[fækt]", pos: "n.", cat: "日常表達 💬", ex: "It is a fact that water turns to ice.", ex_zh: "水遇冷會結成冰是科學事實。" },
  { id: 332, en: "factory", zh: "工廠", kk: "[ˈfæktəri]", pos: "n.", cat: "社會與生活 🏢", ex: "The toy factory makes lovely dolls.", ex_zh: "這家玩具工廠製造好多可愛的洋娃娃。" },
  { id: 333, en: "fail", zh: "失敗", kk: "[fel]", pos: "v.", cat: "動作與思考 🧠", ex: "Never give up even if you fail once.", ex_zh: "就算失敗了一次也千萬不要輕易放棄。" },
  { id: 334, en: "fall", zh: "秋天/跌倒", kk: "[fɔl]", pos: "n./v.", cat: "時間與天氣 ☀️", ex: "Golden leaves fall to the ground.", ex_zh: "金黃色的落葉紛紛飄落到地面上。" },
  { id: 335, en: "family", zh: "家庭", kk: "[ˈfæməli]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "I love my warm and caring family.", ex_zh: "我好愛我那溫暖又體貼的家庭。" },
  { id: 336, en: "famous", zh: "有名的", kk: "[ˈfeməs]", pos: "adj.", cat: "人物與角色 👥", ex: "Taipei 101 is famous around the world.", ex_zh: "台北 101 大樓世界聞名。" },
  { id: 337, en: "fan", zh: "迷/風扇", kk: "[fæn]", pos: "n.", cat: "日常用品 🎒", ex: "Turn on the fan on hot summer days.", ex_zh: "炎熱的夏天記得把電風扇打開。" },
  { id: 338, en: "far", zh: "遠的", kk: "[fɑr]", pos: "adj./adv.", cat: "方向與位置 📍", ex: "The library is not far from our school.", ex_zh: "圖書館離我們學校其實並不遠。" },
  { id: 339, en: "farm", zh: "農田/農場", kk: "[fɑrm]", pos: "n.", cat: "動物與自然 🐶", ex: "Cows and sheep graze on the green farm.", ex_zh: "乳牛與綿羊在翠綠的農場上吃草。" },
  { id: 340, en: "farmer", zh: "農夫", kk: "[ˈfɑrmɚ]", pos: "n.", cat: "人物與角色 👥", ex: "The farmer works hard under the sun.", ex_zh: "辛勤的農夫在艷陽底下認真耕作。" },
  { id: 341, en: "fast", zh: "快的", kk: "[fæst]", pos: "adj./adv.", cat: "情緒與特質 😊", ex: "Cheetahs run fast across grasslands.", ex_zh: "獵豹在廣闊的草原上飛快奔馳。" },
  { id: 342, en: "fat", zh: "胖的/脂肪", kk: "[fæt]", pos: "adj./n.", cat: "身體與健康 🦵", ex: "The round cat is healthy and fat.", ex_zh: "這隻圓滾滾的貓咪健康又胖嘟嘟的。" },
  { id: 343, en: "father", zh: "父親", kk: "[ˈfɑðɚ]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "My father tells funny bedtime stories.", ex_zh: "我的父親常說有趣的睡前故事給我聽。" },
  { id: 344, en: "favorite", zh: "最喜愛的", kk: "[ˈfevərɪt]", pos: "adj./n.", cat: "情緒與特質 😊", ex: "Pizza is my favorite meal of all.", ex_zh: "披薩是我所有食物中最喜歡吃的一道。" },
  { id: 345, en: "February", zh: "二月", kk: "[ˈfɛbjuˌɛri]", pos: "n.", cat: "時間與日常 ⏰", ex: "Lunar New Year often comes in February.", ex_zh: "農曆新年常常落在二月份。" },
  { id: 346, en: "feed", zh: "餵食", kk: "[fid]", pos: "v.", cat: "動作與活動 🏃", ex: "Feed the goldfish twice a day.", ex_zh: "一天餵食小金魚兩次就足夠了。" },
  { id: 347, en: "feel", zh: "覺得/感受", kk: "[fil]", pos: "v.", cat: "情緒與特質 😊", ex: "I feel great when drinking warm milk.", ex_zh: "喝了溫熱的牛奶後我覺得通體舒暢。" },
  { id: 348, en: "festival", zh: "節慶", kk: "[ˈfɛstəvəl]", pos: "n.", cat: "時間與日常 ⏰", ex: "Dragon Boat Festival is full of fun.", ex_zh: "端午節是個充滿樂趣的傳統節慶。" },
  { id: 349, en: "fever", zh: "發燒", kk: "[ˈfivɚ]", pos: "n.", cat: "身體與健康 🦵", ex: "Drink plenty of water when having a fever.", ex_zh: "身體發燒時一定要多喝水休息。" },
  { id: 350, en: "few", zh: "少數的", kk: "[fju]", pos: "adj./pron.", cat: "數量與代名詞 🔢", ex: "Few students missed the morning game.", ex_zh: "幾乎很少有同學錯過早上的這場比賽。" },
  { id: 351, en: "fifteen", zh: "十五", kk: "[ˌfɪfˈtin]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Recess lasts for fifteen minutes.", ex_zh: "課間大下課時間總共有十五分鐘。" },
  { id: 352, en: "fifteenth", zh: "第十五", kk: "[ˌfɪfˈtinθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Today is the fifteenth day of the month.", ex_zh: "今天是這個月份的第十五天。" },
  { id: 353, en: "fifth", zh: "第五", kk: "[fɪfθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "We are fifth-grade elementary students.", ex_zh: "我們是活力滿滿的國小五年級學生。" },
  { id: 354, en: "fifty", zh: "五十", kk: "[ˈfɪfti]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Our school hall has fifty clean chairs.", ex_zh: "學校禮堂整齊排列著五十張乾淨的椅子。" },
  { id: 355, en: "fight", zh: "打架/奮戰", kk: "[faɪt]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Never fight with your classmates.", ex_zh: "千萬不要跟身邊的同學打架起衝突。" },
  { id: 356, en: "fill", zh: "裝滿", kk: "[fɪl]", pos: "v.", cat: "動作與活動 🏃", ex: "Fill your water cup before math class.", ex_zh: "上數學課前先去把水杯裝滿。" },
  { id: 357, en: "finally", zh: "最後/終於", kk: "[ˈfaɪnəli]", pos: "adv.", cat: "時間與日常 ⏰", ex: "We finally reached the mountain top.", ex_zh: "我們歷經努力終於爬上了這座山頂。" },
  { id: 358, en: "find", zh: "找到", kk: "[faɪnd]", pos: "v.", cat: "動作與活動 🏃", ex: "Can you find your missing eraser?", ex_zh: "你能找到你那塊弄丟的小橡皮擦嗎？" },
  { id: 359, en: "fine", zh: "很好的/晴朗的", kk: "[faɪn]", pos: "adj.", cat: "情緒與特質 😊", ex: "I am feeling fine and ready for school.", ex_zh: "我感覺棒極了，已經準備好去上學了。" },
  { id: 360, en: "finger", zh: "手指", kk: "[ˈfɪŋɡɚ]", pos: "n.", cat: "身體與健康 🦵", ex: "Point with your finger at the map.", ex_zh: "用你的小手指在地圖上指出來位置。" },
  { id: 361, en: "finish", zh: "完成", kk: "[ˈfɪnɪʃ]", pos: "v.", cat: "學校與學習 📚", ex: "Finish your daily reading on time.", ex_zh: "準時完成你每天的故事閱讀進度。" },
  { id: 362, en: "fire", zh: "火", kk: "[faɪr]", pos: "n.", cat: "動物與自然 🐶", ex: "Stay away from open fire for safety.", ex_zh: "為了大家的安全，請遠離明火危險。" },
  { id: 363, en: "first", zh: "第一", kk: "[fɝst]", pos: "num./adv.", cat: "數量與代名詞 🔢", ex: "Safety always comes first in school.", ex_zh: "在校園生活中，安全永遠擺在第一位。" },
  { id: 364, en: "fish", zh: "魚/釣魚", kk: "[fɪʃ]", pos: "n./v.", cat: "動物與自然 🐶", ex: "Colorful fish swim inside the tank.", ex_zh: "五顏六色的熱帶魚在魚缸裡悠游著。" },
  { id: 365, en: "fisherman", zh: "漁夫", kk: "[ˈfɪʃɚmən]", pos: "n.", cat: "人物與角色 👥", ex: "The fisherman catches fish in the sea.", ex_zh: "辛勤的漁夫在汪洋大海上捕撈魚貨。" },
  { id: 366, en: "five", zh: "五", kk: "[faɪv]", pos: "num.", cat: "數量與代名詞 🔢", ex: "We master five English words every day.", ex_zh: "我們每天都能熟練掌握五個英文單字。" },
  { id: 367, en: "fix", zh: "修理", kk: "[fɪks]", pos: "v.", cat: "日常用品 🎒", ex: "Dad can fix the broken bicycle chain.", ex_zh: "爸爸能動手把脫落的腳踏車鏈條修好。" },
  { id: 368, en: "floor", zh: "地板/樓層", kk: "[flɔr]", pos: "n.", cat: "居家與建築 🏡", ex: "Mop the classroom floor clean and dry.", ex_zh: "把教室的地板拖洗得乾淨又乾爽。" },
  { id: 369, en: "flower", zh: "花朵", kk: "[ˈflaʊɚ]", pos: "n.", cat: "動物與自然 🐶", ex: "Bright flowers bloom in the school garden.", ex_zh: "校園小花園裡盛開著鮮豔美麗的花朵。" },
  { id: 370, en: "flute", zh: "笛子/長笛", kk: "[flut]", pos: "n.", cat: "學校與學習 📚", ex: "She plays the flute in the school band.", ex_zh: "她在學校的樂團裡吹奏動聽的長笛。" },
  { id: 371, en: "fly", zh: "飛/蒼蠅", kk: "[flaɪ]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Birds fly freely in the blue sky.", ex_zh: "小鳥在蔚藍廣闊的天空中自由飛翔。" },
  { id: 372, en: "follow", zh: "遵循/跟隨", kk: "[ˈfɑlo]", pos: "v.", cat: "動作與活動 🏃", ex: "Always follow the traffic rules safely.", ex_zh: "行走在路上一定要確實遵守交通規則。" },
  { id: 373, en: "food", zh: "食物", kk: "[fud]", pos: "n.", cat: "食物與飲品 🍕", ex: "Eat healthy food to grow tall and strong.", ex_zh: "多吃健康的食物，才能長得又高又壯。" },
  { id: 374, en: "foot", zh: "腳/英尺", kk: "[fʊt]", pos: "n.", cat: "身體與健康 🦵", ex: "We walk to school on foot every morning.", ex_zh: "每天早晨我們都結伴步行去學校。" },
  { id: 375, en: "for", zh: "為了/給", kk: "[fɔr]", pos: "prep.", cat: "日常表達 💬", ex: "This small gift is prepared for you.", ex_zh: "這份小禮物是特別為你用心準備的。" },
  { id: 376, en: "foreign", zh: "外國的", kk: "[ˈfɔrən]", pos: "adj.", cat: "地點與空間 🗺️", ex: "Learning a foreign language is fun.", ex_zh: "學習一門外國語言其實是一件很有趣的事。" },
  { id: 377, en: "foreigner", zh: "外國人", kk: "[ˈfɔrənɚ]", pos: "n.", cat: "人物與角色 👥", ex: "We welcomed foreign guests with smiles.", ex_zh: "我們帶著燦爛的微笑熱情歡迎外國貴賓。" },
  { id: 378, en: "forget", zh: "忘記", kk: "[fɚˈɡɛt]", pos: "v.", cat: "動作與思考 🧠", ex: "Don't forget to pack your homework.", ex_zh: "出門前千萬別忘記把作業放進書包。" },
  { id: 379, en: "fork", zh: "叉子", kk: "[fɔrk]", pos: "n.", cat: "日常用品 🎒", ex: "Use a fork to eat delicious pasta.", ex_zh: "用叉子吃著熱騰騰好吃的義大利麵。" },
  { id: 380, en: "forty", zh: "四十", kk: "[ˈfɔrti]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Each class period lasts forty minutes.", ex_zh: "每一節課的上課時間都是四十分鐘。" },
  { id: 381, en: "four", zh: "四", kk: "[fɔr]", pos: "num.", cat: "數量與代名詞 🔢", ex: "There are four seasons in a year.", ex_zh: "一年四季春夏秋冬，各有不同的景色。" },
  { id: 382, en: "fourteen", zh: "十四", kk: "[ˌfɔrˈtin]", pos: "num.", cat: "數量與代名詞 🔢", ex: "My cousin is fourteen years old.", ex_zh: "我的堂哥今年剛好滿十四歲了。" },
  { id: 383, en: "fourteenth", zh: "第十四", kk: "[ˌfɔrˈtinθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Valentine's Day is on February fourteenth.", ex_zh: "西洋情人節落在二月十四日這一天。" },
  { id: 384, en: "fourth", zh: "第四", kk: "[fɔrθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "April is the fourth month of the year.", ex_zh: "四月是一年當中的第四個月份。" },
  { id: 385, en: "fox", zh: "狐狸", kk: "[fɑks]", pos: "n.", cat: "動物與自然 🐶", ex: "The clever fox has a bushy tail.", ex_zh: "聰明機伶的狐狸長著蓬鬆的大尾巴。" },
  { id: 386, en: "free", zh: "空閒的/免費的", kk: "[fri]", pos: "adj.", cat: "日常表達 💬", ex: "Are you free to play tag after class?", ex_zh: "下課後你有空跟我一起玩抓人遊戲嗎？" },
  { id: 387, en: "French fries", zh: "薯條", kk: "[frɛntʃ fraɪz]", pos: "n.", cat: "食物與飲品 🍕", ex: "Hot French fries taste crunchy and good.", ex_zh: "熱呼呼的炸薯條吃起來酥脆可口。" },
  { id: 388, en: "fresh", zh: "新鮮的", kk: "[frɛʃ]", pos: "adj.", cat: "食物與飲品 🍕", ex: "Drink fresh milk to stay strong.", ex_zh: "天天喝新鮮牛奶，身體長得強壯。" },
  { id: 389, en: "Friday", zh: "星期五", kk: "[ˈfraɪde]", pos: "n.", cat: "時間與日常 ⏰", ex: "Friday afternoon brings weekend smiles.", ex_zh: "每到星期五下午大家都帶著期待的微笑。" },
  { id: 390, en: "friend", zh: "朋友", kk: "[frɛnd]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "A good friend shares joy and laughter.", ex_zh: "好朋友會一同分享彼此的喜悅與歡笑。" },
  { id: 391, en: "friendly", zh: "友善的", kk: "[ˈfrɛndli]", pos: "adj.", cat: "情緒與特質 😊", ex: "Our new classmate is very friendly.", ex_zh: "我們班新來的轉學生為人非常和藹友善。" },
  { id: 392, en: "frisbee", zh: "飛盤", kk: "[ˈfrɪzbi]", pos: "n.", cat: "體育與運動 🏅", ex: "We throw the colorful frisbee in the park.", ex_zh: "我們在公園大草坪上開心地拋擲飛盤。" },
  { id: 393, en: "frog", zh: "青蛙", kk: "[frɔɡ]", pos: "n.", cat: "動物與自然 🐶", ex: "The green frog can jump very high.", ex_zh: "綠油油的青蛙可以跳得非常非常高。" },
  { id: 394, en: "from", zh: "從……來", kk: "[frʌm]", pos: "prep.", cat: "方向與位置 📍", ex: "We walk home together from school.", ex_zh: "放學後我們結伴一起從學校走路回家。" },
  { id: 395, en: "front", zh: "前面", kk: "[frʌnt]", pos: "n./adj.", cat: "方向與位置 📍", ex: "Wait for me in front of the gate.", ex_zh: "請在學校大門口正前方稍微等我一下。" },
  { id: 396, en: "fruit", zh: "水果", kk: "[frut]", pos: "n.", cat: "食物與飲品 🍕", ex: "Fresh fruit is full of natural sweetness.", ex_zh: "新鮮多汁的水果富含天然純淨的甜味。" },
  { id: 397, en: "fry", zh: "油炸/煎", kk: "[fraɪ]", pos: "v.", cat: "食物與飲品 🍕", ex: "Dad can fry delicious eggs for us.", ex_zh: "爸爸很擅長為我們煎出美味噴香的荷包蛋。" },
  { id: 398, en: "full", zh: "滿的/飽的", kk: "[fʊl]", pos: "adj.", cat: "情緒與特質 😊", ex: "I feel full after eating yummy dumplings.", ex_zh: "吃完香噴噴的水餃之後我的肚子好飽喔。" },
  { id: 399, en: "fun", zh: "樂趣/有趣的", kk: "[fʌn]", pos: "n./adj.", cat: "情緒與特質 😊", ex: "Learning English with games is so much fun.", ex_zh: "透過闖關遊戲學英文真是有趣極了。" },
  { id: 400, en: "funny", zh: "好笑的/有趣的", kk: "[ˈfʌni]", pos: "adj.", cat: "情緒與特質 😊", ex: "Teacher told a very funny joke today.", ex_zh: "老師今天在課堂上說了一個超級好笑的笑話。" },
  { id: 401, en: "future", zh: "未來", kk: "[ˈfjutʃɚ]", pos: "n.", cat: "時間與日常 ⏰", ex: "Work hard today for a bright future.", ex_zh: "今天認真踏實努力，開創美好的未來。" },
  { id: 402, en: "game", zh: "比賽/遊戲", kk: "[ɡem]", pos: "n.", cat: "體育與運動 🏅", ex: "Let's play a word-matching game now.", ex_zh: "現在讓我們一起來玩英文單字配對遊戲吧。" },
  { id: 403, en: "garbage", zh: "垃圾", kk: "[ˈɡɑrbɪdʒ]", pos: "n.", cat: "日常用品 🎒", ex: "Throw garbage into the trash can.", ex_zh: "請養成把垃圾順手丟進垃圾桶的好習慣。" },
  { id: 404, en: "garden", zh: "花園", kk: "[ˈɡɑrdn]", pos: "n.", cat: "動物與自然 🐶", ex: "Bees buzz around the colorful garden.", ex_zh: "蜜蜂在繽紛的花園裡忙碌地穿梭採蜜。" },
  { id: 405, en: "gas", zh: "瓦斯/氣體", kk: "[ɡæs]", pos: "n.", cat: "日常用品 🎒", ex: "Turn off the gas stove safely after cooking.", ex_zh: "煮完東西後一定要確認關好瓦斯爐開關。" },
  { id: 406, en: "gate", zh: "大門", kk: "[ɡet]", pos: "n.", cat: "居家與建築 🏡", ex: "Meet me at the school front gate.", ex_zh: "放學後我們在學校的正門口碰面吧。" },
  { id: 407, en: "get", zh: "得到/變成", kk: "[ɡɛt]", pos: "v.", cat: "動作與活動 🏃", ex: "You get a gold star for doing well.", ex_zh: "因為表現非常優秀，你獲得了一顆金星星！" },
  { id: 408, en: "ghost", zh: "鬼/幽靈", kk: "[ɡost]", pos: "n.", cat: "動物與自然 🐶", ex: "Kids dress up like ghosts on Halloween.", ex_zh: "萬聖節時小朋友會把自己打扮成淘氣的小鬼。" },
  { id: 409, en: "giant", zh: "巨大的/巨人", kk: "[ˈdʒaɪənt]", pos: "adj./n.", cat: "情緒與特質 😊", ex: "An elephant is a giant animal.", ex_zh: "大象是陸地上體型極為龐大的動物。" },
  { id: 410, en: "gift", zh: "禮物", kk: "[ɡɪft]", pos: "n.", cat: "日常用品 🎒", ex: "I received a wonderful gift on my birthday.", ex_zh: "我在生日時收到了一份非常棒的精緻禮物。" },
  { id: 411, en: "girl", zh: "女孩", kk: "[ɡɝl]", pos: "n.", cat: "人物與角色 👥", ex: "That kind girl loves helping other kids.", ex_zh: "那個善良貼心的小女孩總是很樂於助人。" },
  { id: 412, en: "give", zh: "給予", kk: "[ɡɪv]", pos: "v.", cat: "動作與活動 🏃", ex: "Give your classmate a warm high five.", ex_zh: "給身旁的好同學一個熱情溫暖的擊掌！" },
  { id: 413, en: "glad", zh: "高興的", kk: "[ɡlæd]", pos: "adj.", cat: "情緒與特質 😊", ex: "I am glad to see you again today.", ex_zh: "今天能再次看到你，我真的覺得很高興。" },
  { id: 414, en: "glass", zh: "玻璃杯/玻璃", kk: "[ɡlæs]", pos: "n.", cat: "日常用品 🎒", ex: "Pour some cold juice into this glass.", ex_zh: "把冰涼的果汁倒進這個透明玻璃杯裡吧。" },
  { id: 415, en: "glasses", zh: "眼鏡", kk: "[ˈɡlæsɪz]", pos: "n.", cat: "衣著與配件 👕", ex: "Teacher Pomelo wears neat round glasses.", ex_zh: "柚子老師戴著一副斯文又可愛的圓圓眼鏡。" },
  { id: 416, en: "glove", zh: "手套", kk: "[ɡlʌv]", pos: "n.", cat: "衣著與配件 👕", ex: "Wear warm gloves on chilly winter mornings.", ex_zh: "在寒冷的冬日清晨記得戴上保暖的手套。" },
  { id: 417, en: "glue", zh: "膠水/黏貼", kk: "[ɡlu]", pos: "n./v.", cat: "學校與學習 📚", ex: "Use glue to paste pictures on paper.", ex_zh: "用膠水把剪好的圖片整齊黏在圖畫紙上。" },
  { id: 418, en: "go", zh: "去/走", kk: "[ɡo]", pos: "v.", cat: "動作與活動 🏃", ex: "Let's go to the playground together.", ex_zh: "大家手牽手一起前往操場玩耍吧。" },
  { id: 419, en: "goat", zh: "山羊", kk: "[ɡot]", pos: "n.", cat: "動物與自然 🐶", ex: "The little goat climbs the rocky hill.", ex_zh: "敏捷的小山羊輕鬆爬上了崎嶇的小山坡。" },
  { id: 420, en: "good", zh: "好的", kk: "[ɡʊd]", pos: "adj.", cat: "情緒與特質 😊", ex: "Have a good and energetic morning!", ex_zh: "祝你有個元氣滿滿又美好的活力早晨！" },
  { id: 421, en: "goodbye", zh: "再見", kk: "[ˌɡʊdˈbaɪ]", pos: "interj.", cat: "日常表達 💬", ex: "Wave your hand and say goodbye.", ex_zh: "揮揮手向大家禮貌地說聲再見囉。" },
  { id: 422, en: "goose", zh: "鵝", kk: "[ɡus]", pos: "n.", cat: "動物與自然 🐶", ex: "The white goose waddles by the pond.", ex_zh: "大白鵝搖搖擺擺地在池塘邊漫步。" },
  { id: 423, en: "grade", zh: "成績/年級", kk: "[ɡred]", pos: "n.", cat: "學校與學習 📚", ex: "He gets good grades through hard work.", ex_zh: "他透過每天踏實努力在學業上取得好成績。" },
  { id: 424, en: "gram", zh: "公克", kk: "[ɡræm]", pos: "n.", cat: "數量與代名詞 🔢", ex: "This small chocolate bar weighs fifty grams.", ex_zh: "這塊小巧的巧克力總共重達五十公克。" },
  { id: 425, en: "grandfather", zh: "祖父/外祖父", kk: "[ˈɡrændˌfɑðɚ]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "My grandfather goes walking every morning.", ex_zh: "我的爺爺每天清晨都會出門散步運動。" },
  { id: 426, en: "grandmother", zh: "祖母/外祖母", kk: "[ˈɡrændˌmʌðɚ]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "Grandmother bakes sweet apple pies for us.", ex_zh: "奶奶親手為我們烤了香甜的蘋果派。" },
  { id: 427, en: "grape", zh: "葡萄", kk: "[ɡrep]", pos: "n.", cat: "食物與飲品 🍕", ex: "Purple grapes are sweet and juicy.", ex_zh: "紫瑩瑩的葡萄吃起來既香甜又多汁。" },
  { id: 428, en: "grass", zh: "草地/青草", kk: "[ɡræs]", pos: "n.", cat: "動物與自然 🐶", ex: "Do not step on the green grass.", ex_zh: "請發揮愛心，不要任意踩踏翠綠的草皮。" },
  { id: 429, en: "gray", zh: "灰色的", kk: "[ɡre]", pos: "adj./n.", cat: "色彩與形狀 🎨", ex: "Rain clouds in the sky look gloomy and gray.", ex_zh: "天空中的烏雲看起來灰濛濛的，快要下雨了。" },
  { id: 430, en: "great", zh: "很棒的/巨大的", kk: "[ɡret]", pos: "adj.", cat: "情緒與特質 😊", ex: "You did a great job today, keep it up!", ex_zh: "你今天表現得超級棒，請繼續保持喔！" },
  { id: 431, en: "green", zh: "綠色(的)", kk: "[ɡrin]", pos: "adj./n.", cat: "色彩與形狀 🎨", ex: "Spring turns the trees fresh and green.", ex_zh: "溫暖的春天讓大地上的樹木換上一身鮮綠。" },
  { id: 432, en: "ground", zh: "地面", kk: "[ɡraʊnd]", pos: "n.", cat: "地點與空間 🗺️", ex: "Sit down on the ground in a big circle.", ex_zh: "大家一起在草地上圍坐成一個大圓圈。" },
  { id: 433, en: "group", zh: "團體/小組", kk: "[ɡrup]", pos: "n.", cat: "學校與學習 📚", ex: "Work together in your learning group.", ex_zh: "在學習小組裡面大家要齊心協力合作。" },
  { id: 434, en: "grow", zh: "種植/成長", kk: "[ɡro]", pos: "v.", cat: "動物與自然 🐶", ex: "Water the seeds and watch them grow tall.", ex_zh: "給種子澆澆水，看著它們漸漸抽芽長高。" },
  { id: 435, en: "guava", zh: "番石榴/芭樂", kk: "[ˈɡwɑvə]", pos: "n.", cat: "食物與飲品 🍕", ex: "Taiwan guavas are sweet, crunchy, and tasty.", ex_zh: "台灣出產的芭樂吃起來香脆又多汁美味。" },
  { id: 436, en: "guess", zh: "猜想", kk: "[ɡɛs]", pos: "v./n.", cat: "動作與思考 🧠", ex: "Can you guess what is inside this secret box?", ex_zh: "你能猜得出這個神秘盒子裡裝著什麼嗎？" },
  { id: 437, en: "guitar", zh: "吉他", kk: "[ɡɪˈtɑr]", pos: "n.", cat: "學校與學習 📚", ex: "He plays songs on his wooden guitar.", ex_zh: "他用一把溫潤的木吉他彈奏著動人的歌曲。" },
  { id: 438, en: "guy", zh: "傢伙/夥伴", kk: "[ɡaɪ]", pos: "n.", cat: "人物與角色 👥", ex: "That guy is friendly and easy to talk to.", ex_zh: "那個大男孩人很和藹，非常好相處。" },
  { id: 439, en: "gym", zh: "體育館", kk: "[dʒɪm]", pos: "n.", cat: "學校與學習 📚", ex: "We play basketball inside the gym when it rains.", ex_zh: "下雨天時我們就會改在室內體育館裡打籃球。" },
  { id: 440, en: "habit", zh: "習慣", kk: "[ˈhæbɪt]", pos: "n.", cat: "社會與生活 🏢", ex: "Reading every day is a wonderful habit.", ex_zh: "每天花點時間閱讀是一個非常棒的好習慣。" },
  { id: 441, en: "hair", zh: "頭髮", kk: "[hɛr]", pos: "n.", cat: "身體與健康 🦵", ex: "Brush your hair neatly before going to school.", ex_zh: "出門上學之前記得要把頭髮梳理整齊。" },
  { id: 442, en: "half", zh: "一半", kk: "[hæf]", pos: "n./adj.", cat: "數量與代名詞 🔢", ex: "Share half of your sweet orange with your friend.", ex_zh: "把甜甜的柳橙分一半給身邊的好朋友吧。" },
  { id: 443, en: "Halloween", zh: "萬聖節", kk: "[ˌhæloˈin]", pos: "n.", cat: "時間與日常 ⏰", ex: "Say trick or treat on Halloween night!", ex_zh: "在萬聖節的夜晚開心地喊出不給糖就搗蛋！" },
  { id: 444, en: "ham", zh: "火腿", kk: "[hæm]", pos: "n.", cat: "食物與飲品 🍕", ex: "Put a slice of ham inside your sandwich.", ex_zh: "在美味的三明治裡夾進一片香噴噴的火腿。" },
  { id: 445, en: "hamburger", zh: "漢堡", kk: "[ˈhæmbɝɡɚ]", pos: "n.", cat: "食物與飲品 🍕", ex: "Dad made a big beef hamburger for lunch.", ex_zh: "爸爸在午餐時親手為我做了一個大牛肉漢堡。" },
  { id: 446, en: "hand", zh: "手", kk: "[hænd]", pos: "n.", cat: "身體與健康 🦵", ex: "Wash your hands with soap before eating meals.", ex_zh: "吃東西之前記得先用肥皂把雙手清洗乾淨。" },
  { id: 447, en: "handsome", zh: "英俊的", kk: "[ˈhænsəm]", pos: "adj.", cat: "人物與角色 👥", ex: "He looks neat, polite, and very handsome.", ex_zh: "他看起來乾淨整齊、彬彬有禮而且十分帥氣。" },
  { id: 448, en: "hang", zh: "懸掛", kk: "[hæŋ]", pos: "v.", cat: "動作與活動 🏃", ex: "Hang your jacket on the chair hook.", ex_zh: "把你的外套整齊掛在椅子旁邊的掛鉤上。" },
  { id: 449, en: "happen", zh: "發生", kk: "[ˈhæpən]", pos: "v.", cat: "日常表達 💬", ex: "Tell me what happened during recess time.", ex_zh: "快跟我說說看剛才下課時到底發生了什麼事。" },
  { id: 450, en: "happy", zh: "快樂的", kk: "[ˈhæpi]", pos: "adj.", cat: "情緒與特質 😊", ex: "We feel happy when playing with our friends.", ex_zh: "和好朋友聚在一起玩耍時大家都感到無比快樂。" }
