  { id: 451, en: "hard", zh: "困難的/努力的", kk: "[hɑrd]", pos: "adj./adv.", cat: "能力與特質 🌟", ex: "Study hard and you will do well.", ex_zh: "努力用功學習，你一定會有好表現。" },
  { id: 452, en: "hard-working", zh: "努力工作的/勤勉的", kk: "[ˈhɑrdˌwɝkɪŋ]", pos: "adj.", cat: "能力與特質 🌟", ex: "Ants are small but hard-working animals.", ex_zh: "螞蟻雖然體型微小，卻是非常勤勉的動物。" },
  { id: 453, en: "hat", zh: "帽子", kk: "[hæt]", pos: "n.", cat: "衣著與配件 👕", ex: "She wears a pretty straw hat in summer.", ex_zh: "夏天時她常戴著一頂漂亮的草帽遮陽。" },
  { id: 454, en: "hate", zh: "討厭", kk: "[het]", pos: "v.", cat: "情緒與特質 😊", ex: "I hate getting up late on school days.", ex_zh: "在上學日我最討厭自己賴床睡過頭了。" },
  { id: 455, en: "have", zh: "有/吃", kk: "[hæv]", pos: "v.", cat: "日常表達 💬", ex: "We have fun games in English class.", ex_zh: "我們在英文課上玩了好多好玩的遊戲。" },
  { id: 456, en: "he", zh: "他", kk: "[hi]", pos: "pron.", cat: "數量與代名詞 🔢", ex: "He is the fastest runner in our school.", ex_zh: "他是我們全校跑步速度最快的小飛俠。" },
  { id: 457, en: "head", zh: "頭", kk: "[hɛd]", pos: "n.", cat: "身體與健康 🦵", ex: "Nod your head if you understand this rule.", ex_zh: "如果你聽懂了這個規則就點點頭吧。" },
  { id: 458, en: "headache", zh: "頭痛", kk: "[ˈhɛdˌek]", pos: "n.", cat: "身體與健康 🦵", ex: "Take a quiet rest when you have a headache.", ex_zh: "頭痛的時候請安靜躺下來閉目休息。" },
  { id: 459, en: "health", zh: "健康", kk: "[hɛlθ]", pos: "n.", cat: "身體與健康 🦵", ex: "Good food and sports bring good health.", ex_zh: "均衡營養與規律運動能帶來充沛的健康。" },
  { id: 460, en: "healthy", zh: "健康的", kk: "[ˈhɛlθi]", pos: "adj.", cat: "身體與健康 🦵", ex: "Eating green vegetables keeps you healthy.", ex_zh: "多吃新鮮綠色蔬菜能保持身體健康無病痛。" },
  { id: 461, en: "hear", zh: "聽見", kk: "[hɪr]", pos: "v.", cat: "動作與思考 🧠", ex: "I can hear the sweet singing of birds.", ex_zh: "我能清楚聽見小鳥在窗外唱著動聽的歌。" },
  { id: 462, en: "heart", zh: "心/心臟", kk: "[hɑrt]", pos: "n.", cat: "身體與健康 🦵", ex: "Draw a red heart to show your love.", ex_zh: "畫上一顆紅色愛心來表達你滿滿的感謝。" },
  { id: 463, en: "heat", zh: "熱度/加熱", kk: "[hit]", pos: "n./v.", cat: "時間與天氣 ☀️", ex: "Summer heat makes us want cold watermelon.", ex_zh: "夏天的炎熱高溫讓人好想吃冰涼的西瓜。" },
  { id: 464, en: "heavy", zh: "重的", kk: "[ˈhɛvi]", pos: "adj.", cat: "能力與特質 🌟", ex: "This school bag is too heavy for you.", ex_zh: "這個大書包對你來說裝得太過沉重了。" },
  { id: 465, en: "hello", zh: "喂/你好", kk: "[həˈlo]", pos: "interj.", cat: "日常表達 💬", ex: "Say hello politely to your teacher every morning.", ex_zh: "每天早晨見到老師要記得有禮貌地打招呼說你好。" },
  { id: 466, en: "help", zh: "幫忙/協助", kk: "[hɛlp]", pos: "v./n.", cat: "能力與特質 🌟", ex: "Good friends always help each other.", ex_zh: "好朋友總是會在需要的時候互相伸出援手。" },
  { id: 467, en: "helpful", zh: "有幫助的", kk: "[ˈhɛlpfəl]", pos: "adj.", cat: "能力與特質 🌟", ex: "You are a very helpful little student.", ex_zh: "你真是一個非常熱心助人的好學生。" },
  { id: 468, en: "hen", zh: "母雞", kk: "[hɛn]", pos: "n.", cat: "動物與自然 🐶", ex: "The brown hen lays an egg every day.", ex_zh: "那隻棕色母雞每天都會下一顆新鮮雞蛋。" },
  { id: 469, en: "here", zh: "這裡", kk: "[hɪr]", pos: "adv.", cat: "方向與位置 📍", ex: "Come over here and sit with me.", ex_zh: "快走過來這裡跟我並肩坐在一起吧。" },
  { id: 470, en: "hey", zh: "嘿", kk: "[he]", pos: "interj.", cat: "日常表達 💬", ex: "Hey, look at that colorful hot-air balloon!", ex_zh: "嘿，快抬頭看看那個色彩斑斕的熱氣球！" },
  { id: 471, en: "hi", zh: "嗨", kk: "[haɪ]", pos: "interj.", cat: "日常表達 💬", ex: "Hi everyone, welcome back to school!", ex_zh: "嗨大家，熱烈歡迎大家平安回到校園！" },
  { id: 472, en: "hide", zh: "隱藏/躲藏", kk: "[haɪd]", pos: "v.", cat: "動作與活動 🏃", ex: "Let's play hide and seek in the park.", ex_zh: "我們一起在公園裡玩刺激好玩的捉迷藏吧。" },
  { id: 473, en: "high", zh: "高的", kk: "[haɪ]", pos: "adj./adv.", cat: "能力與特質 🌟", ex: "Frogs can jump very high into the air.", ex_zh: "小青蛙可以輕盈地跳得非常高。" },
  { id: 474, en: "hike", zh: "徒步旅行/健行", kk: "[haɪk]", pos: "v./n.", cat: "體育與運動 🏅", ex: "We hike up the hill on sunny weekends.", ex_zh: "我們在陽光明媚的週末一起上山健行散步。" },
  { id: 475, en: "hill", zh: "小山/丘陵", kk: "[hɪl]", pos: "n.", cat: "動物與自然 🐶", ex: "Windmills spin fast on top of the hill.", ex_zh: "小山丘頂上的風車正隨著微風快速轉動。" },
  { id: 476, en: "hippo", zh: "河馬", kk: "[ˈhɪpo]", pos: "n.", cat: "動物與自然 🐶", ex: "The heavy hippo enjoys soaking in water.", ex_zh: "體型圓滾龐大的河馬最喜歡泡在涼爽水池裡。" },
  { id: 477, en: "history", zh: "歷史", kk: "[ˈhɪstəri]", pos: "n.", cat: "學校與學習 📚", ex: "Our town has a long and rich history.", ex_zh: "我們居住的小鎮擁有悠久且豐富的歷史文化。" },
  { id: 478, en: "hit", zh: "打擊/碰撞", kk: "[hɪt]", pos: "v.", cat: "動作與活動 🏃", ex: "Hit the baseball hard with your bat.", ex_zh: "雙手握緊球棒，用力把棒球給擊飛出去！" },
  { id: 479, en: "hobby", zh: "嗜好/興趣", kk: "[ˈhɑbi]", pos: "n.", cat: "社會與生活 🏢", ex: "Drawing cartoons is my favorite hobby.", ex_zh: "動手畫畫漫畫是我日常最喜歡的休閒嗜好。" },
  { id: 480, en: "hold", zh: "拿著/握住", kk: "[hold]", pos: "v.", cat: "動作與活動 🏃", ex: "Hold my hand when crossing the busy road.", ex_zh: "過馬路的時候一定要緊緊牽著我的手喔。" },
  { id: 481, en: "holiday", zh: "假日", kk: "[ˈhɑləˌde]", pos: "n.", cat: "時間與日常 ⏰", ex: "We plan to go on a picnic this holiday.", ex_zh: "我們計畫在這個假日全家一起去郊外野餐。" },
  { id: 482, en: "home", zh: "家", kk: "[hom]", pos: "n./adv.", cat: "居家與建築 🏡", ex: "There is no sweet place like home.", ex_zh: "世上沒有任何一個地方比自己家更溫馨了。" },
  { id: 483, en: "homework", zh: "家庭作業", kk: "[ˈhomˌwɝk]", pos: "n.", cat: "學校與學習 📚", ex: "Finish your daily homework before watching TV.", ex_zh: "看電視之前記得先把今天的家庭作業寫完。" },
  { id: 484, en: "honest", zh: "誠實的", kk: "[ˈɑnɪst]", pos: "adj.", cat: "情緒與特質 😊", ex: "An honest student tells the truth always.", ex_zh: "誠實正直的學生總是會勇敢說出事實真相。" },
  { id: 485, en: "honey", zh: "蜂蜜/寶貝", kk: "[ˈhʌni]", pos: "n.", cat: "食物與飲品 🍕", ex: "Sweet honey comes from busy little bees.", ex_zh: "香甜可口的純蜂蜜來自於辛勤耕耘的小蜜蜂。" },
  { id: 486, en: "hop", zh: "(單腳)跳/躍過", kk: "[hɑp]", pos: "v.", cat: "動作與活動 🏃", ex: "Rabbits hop quickly across green grass.", ex_zh: "小白兔在翠綠青草地上輕快地跳躍穿梭。" },
  { id: 487, en: "hope", zh: "希望", kk: "[hop]", pos: "v./n.", cat: "情緒與特質 😊", ex: "I hope you have a wonderful school year.", ex_zh: "我由衷祝福並希望你有個收穫滿滿的新學年。" },
  { id: 488, en: "horse", zh: "馬", kk: "[hɔrs]", pos: "n.", cat: "動物與自然 🐶", ex: "The brown horse runs fast across the field.", ex_zh: "那匹棕色駿馬在原野上飛快地奔騰馳騁。" },
  { id: 489, en: "hospital", zh: "醫院", kk: "[ˈhɑspɪtl]", pos: "n.", cat: "地點與交通 🚌", ex: "Doctors and kind nurses work in the hospital.", ex_zh: "醫生與親切的護士們在醫院裡照顧生病的人。" },
  { id: 490, en: "hot", zh: "熱的/辣的", kk: "[hɑt]", pos: "adj.", cat: "時間與天氣 ☀️", ex: "Be careful with this cup of hot soup.", ex_zh: "端著這碗熱呼呼的熱湯時請務必小心別燙著。" },
  { id: 491, en: "hot dog", zh: "熱狗", kk: "[hɑt dɔɡ]", pos: "n.", cat: "食物與飲品 🍕", ex: "I ordered a hot dog with tomato sauce.", ex_zh: "我在攤位點了一份淋上香甜番茄醬的熱狗。" },
  { id: 492, en: "hotel", zh: "旅社/飯店", kk: "[hoˈtɛl]", pos: "n.", cat: "居家與建築 🏡", ex: "We stayed in a cozy hotel by the beach.", ex_zh: "我們在海灘旁邊那家溫馨舒適的飯店住宿。" },
  { id: 493, en: "hour", zh: "小時", kk: "[aʊr]", pos: "n.", cat: "時間與日常 ⏰", ex: "We practice speaking English for one hour.", ex_zh: "我們認真投入練習開口說英語達一個小時。" },
  { id: 494, en: "house", zh: "房屋", kk: "[haʊs]", pos: "n.", cat: "居家與建築 🏡", ex: "Their house has a pretty little front yard.", ex_zh: "他們的房子前面有一個精緻漂亮的小庭院。" },
  { id: 495, en: "housewife", zh: "家庭主婦", kk: "[ˈhaʊsˌwaɪf]", pos: "n.", cat: "人物與角色 👥", ex: "Mom is a busy housewife who cares for us.", ex_zh: "媽媽是一位每天細心打理家務並照顧全家的主婦。" },
  { id: 496, en: "how", zh: "如何/怎樣", kk: "[haʊ]", pos: "adv.", cat: "日常表達 💬", ex: "How are you doing on this sunny morning?", ex_zh: "在這個陽光明媚的美好早晨，你最近過得如何呢？" },
  { id: 497, en: "however", zh: "然而/無論如何", kk: "[haʊˈɛvɚ]", pos: "adv.", cat: "日常表達 💬", ex: "It rained hard; however, we still had fun.", ex_zh: "外頭雨下得很大；然而，我們依然玩得很盡興。" },
  { id: 498, en: "hundred", zh: "百", kk: "[ˈhʌndrəd]", pos: "num.", cat: "數量與代名詞 🔢", ex: "One hundred cents make one full dollar.", ex_zh: "每一百個分錢就能整整折合為一元。" },
  { id: 499, en: "hungry", zh: "飢餓的", kk: "[ˈhʌŋɡri]", pos: "adj.", cat: "身體與健康 🦵", ex: "I am hungry and ready for yummy lunch.", ex_zh: "我的肚子咕嚕咕嚕叫，已經準備好吃午餐了！" },
  { id: 500, en: "hunt", zh: "打獵/搜尋", kk: "[hʌnt]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Cats hunt mice quietly in dark barns.", ex_zh: "敏銳的貓咪在幽暗的穀倉裡悄無聲息地抓老鼠。" },
  { id: 501, en: "hurry", zh: "趕忙/匆忙", kk: "[ˈhɝi]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Hurry up or we will be late for class.", ex_zh: "動作快一點，不然我們上課就要遲到了。" },
  { id: 502, en: "hurt", zh: "受傷/感到疼痛", kk: "[hɝt]", pos: "v./adj.", cat: "身體與健康 🦵", ex: "Wash the cut gently so it does not hurt.", ex_zh: "動作輕一點清洗小傷口，這樣才不會感到刺痛。" },
  { id: 503, en: "husband", zh: "丈夫", kk: "[ˈhʌzbənd]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "Dad is mom's caring husband.", ex_zh: "爸爸是媽媽心目中體貼又顧家的好丈夫。" },
  { id: 504, en: "I", zh: "我", kk: "[aɪ]", pos: "pron.", cat: "數量與代名詞 🔢", ex: "I love reading English fairy tales.", ex_zh: "我非常喜歡閱讀充滿想像力的英文童話故事。" },
  { id: 505, en: "ice", zh: "冰", kk: "[aɪs]", pos: "n.", cat: "時間與天氣 ☀️", ex: "Cold ice cubes melt fast under the sun.", ex_zh: "晶瑩冰涼的冰塊在烈日照射下迅速融化開來。" },
  { id: 506, en: "ice cream", zh: "冰淇淋", kk: "[aɪs krim]", pos: "n.", cat: "食物與飲品 🍕", ex: "Vanilla ice cream tastes sweet and creamy.", ex_zh: "香草口味的冰淇淋吃起來既香甜又綿密順口。" },
  { id: 507, en: "idea", zh: "主意/點子", kk: "[aɪˈdiə]", pos: "n.", cat: "動作與思考 🧠", ex: "You have a brilliant and creative idea!", ex_zh: "你剛才提出了一個非常有創意又精彩的好點子！" },
  { id: 508, en: "if", zh: "如果", kk: "[ɪf]", pos: "conj.", cat: "日常表達 💬", ex: "If it rains tomorrow, we will play inside.", ex_zh: "如果明天下雨的話，我們就改在室內做活動。" },
  { id: 509, en: "important", zh: "重要的", kk: "[ɪmˈpɔrtnt]", pos: "adj.", cat: "情緒與特質 😊", ex: "Drinking water daily is important for health.", ex_zh: "每天補充足量水分對身體健康來說極為重要。" },
  { id: 510, en: "in", zh: "在…裡面", kk: "[ɪn]", pos: "prep.", cat: "方向與位置 📍", ex: "Put your clean notebook in your school bag.", ex_zh: "把你乾淨整潔的筆記本好好收進書包裡面。" },
  { id: 511, en: "insect", zh: "昆蟲", kk: "[ˈɪnsɛkt]", pos: "n.", cat: "動物與自然 🐶", ex: "An ant is a tiny six-legged insect.", ex_zh: "小螞蟻是一種長著六隻腳的微小昆蟲。" },
  { id: 512, en: "inside", zh: "在...內部", kk: "[ɪnˈsaɪd]", pos: "prep./adv.", cat: "方向與位置 📍", ex: "Stay inside the classroom when it storms.", ex_zh: "外頭颳風暴雨時請大家待在教室裡面確保平安。" },
  { id: 513, en: "interest", zh: "使感興趣/利息", kk: "[ˈɪntrɪst]", pos: "v./n.", cat: "情緒與特質 😊", ex: "Science experiments interest our classmates.", ex_zh: "奇妙有趣的科學實驗激起了同學們滿滿的興趣。" },
  { id: 514, en: "interested", zh: "感興趣的", kk: "[ˈɪntrɪstɪd]", pos: "adj.", cat: "情緒與特質 😊", ex: "I am interested in exploring outer space.", ex_zh: "我對探索浩瀚神秘的外太空抱持著極大興趣。" },
  { id: 515, en: "interesting", zh: "有趣的", kk: "[ˈɪntrɪstɪŋ]", pos: "adj.", cat: "情緒與特質 😊", ex: "This dinosaur book is very interesting.", ex_zh: "這本介紹史前恐龍的圖畫書內容非常生動有趣。" },
  { id: 516, en: "interview", zh: "訪問/面試", kk: "[ˈɪntɚˌvju]", pos: "v./n.", cat: "社會與生活 🏢", ex: "Students interview the school principal today.", ex_zh: "校園小記者們今天在校長室採訪親切的校長。" },
  { id: 517, en: "Internet", zh: "網路", kk: "[ˈɪntɚˌnɛt]", pos: "n.", cat: "社會與生活 🏢", ex: "We search for information on the Internet.", ex_zh: "我們在網際網路上搜尋豐富多元的學習資料。" },
  { id: 518, en: "into", zh: "到……之內", kk: "[ˈɪntu]", pos: "prep.", cat: "方向與位置 📍", ex: "Pour fresh milk into the clean cup.", ex_zh: "把香醇的新鮮牛奶倒進乾淨的玻璃杯之中。" },
  { id: 519, en: "invite", zh: "邀請", kk: "[ɪnˈvaɪt]", pos: "v.", cat: "社會與生活 🏢", ex: "Invite your good friends to your birthday party.", ex_zh: "熱情邀請你的好朋友們一起來參加你的生日派對。" },
  { id: 520, en: "island", zh: "島嶼", kk: "[ˈaɪlənd]", pos: "n.", cat: "地點與空間 🗺️", ex: "Taiwan is a beautiful green island.", ex_zh: "台灣是一座四面環海、景色秀麗的綠色島嶼。" },
  { id: 521, en: "it", zh: "它", kk: "[ɪt]", pos: "pron.", cat: "數量與代名詞 🔢", ex: "Look at the cute rabbit; it hops fast.", ex_zh: "快看看那隻小兔子；牠蹦蹦跳跳跑得真敏捷。" },
  { id: 522, en: "jacket", zh: "夾克", kk: "[ˈdʒækɪt]", pos: "n.", cat: "衣著與配件 👕", ex: "Zip up your warm jacket before going out.", ex_zh: "走出門口吹冷風之前先把你暖和的夾克拉好。" },
  { id: 523, en: "January", zh: "一月", kk: "[ˈdʒænjuˌɛri]", pos: "n.", cat: "時間與日常 ⏰", ex: "January is the first fresh month of a year.", ex_zh: "一月份象徵著嶄新一年的開始，是第一個月份。" },
  { id: 524, en: "jeans", zh: "牛仔褲", kk: "[dʒinz]", pos: "n.", cat: "衣著與配件 👕", ex: "Blue jeans are durable and comfy to wear.", ex_zh: "經典的藍色牛仔褲穿起來耐磨又相當自在舒適。" },
  { id: 525, en: "job", zh: "工作", kk: "[dʒɑb]", pos: "n.", cat: "社會與生活 🏢", ex: "Being a loving teacher is a wonderful job.", ex_zh: "成為一位充滿愛心引導孩子的老師是一份美善的工作。" },
  { id: 526, en: "jog", zh: "慢跑", kk: "[dʒɑɡ]", pos: "v./n.", cat: "體育與運動 🏅", ex: "We jog around the school track in gym class.", ex_zh: "我們在體育課時繞著學校操場的跑道輕鬆慢跑。" },
  { id: 527, en: "join", zh: "加入", kk: "[dʒɔɪn]", pos: "v.", cat: "社會與生活 🏢", ex: "Come and join our after-school English club.", ex_zh: "熱烈歡迎大家一起加入我們放學後的英語趣味社團。" },
  { id: 528, en: "joy", zh: "歡樂/喜悅", kk: "[dʒɔɪ]", pos: "n.", cat: "情緒與特質 😊", ex: "Singing together brings our hearts pure joy.", ex_zh: "大家聚在一起歡唱歌曲，為彼此的心靈帶來無比喜悅。" },
  { id: 529, en: "juice", zh: "果汁", kk: "[dʒus]", pos: "n.", cat: "食物與飲品 🍕", ex: "Fresh orange juice is rich in vitamin C.", ex_zh: "現榨的新鮮柳橙汁富含豐富充足的維生素 C。" },
  { id: 530, en: "July", zh: "七月", kk: "[dʒuˈlaɪ]", pos: "n.", cat: "時間與日常 ⏰", ex: "Our summer vacation starts happily in July.", ex_zh: "期待已久的快樂暑假通常在七月份正式拉開序幕。" },
  { id: 531, en: "jump", zh: "跳躍", kk: "[dʒʌmp]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Jump as high as you can in jumping rope.", ex_zh: "在跳繩運動中盡你所能朝向空中輕快地跳躍吧！" },
  { id: 532, en: "June", zh: "六月", kk: "[dʒun]", pos: "n.", cat: "時間與日常 ⏰", ex: "June brings warm sunshine and summer breeze.", ex_zh: "六月份為大地帶來了溫暖耀眼的陽光與夏日微風。" },
  { id: 533, en: "junior high school", zh: "國中", kk: "[ˈdʒunjɚ haɪ skul]", pos: "n.", cat: "學校與學習 📚", ex: "We will enter junior high school next year.", ex_zh: "明年我們就要從小學畢業，升上充滿挑戰的國中了。" },
  { id: 534, en: "just", zh: "只是/剛剛", kk: "[dʒʌst]", pos: "adv.", cat: "日常表達 💬", ex: "I just finished reading this amazing story.", ex_zh: "我才剛剛一口氣讀完了這本令人驚嘆的故事書。" },
  { id: 535, en: "kangaroo", zh: "袋鼠", kk: "[ˌkæŋɡəˈru]", pos: "n.", cat: "動物與自然 🐶", ex: "A mother kangaroo carries her baby in a pouch.", ex_zh: "袋鼠媽媽用肚子前面的育兒袋安全護著小寶寶。" },
  { id: 536, en: "keep", zh: "保持/保存", kk: "[kip]", pos: "v.", cat: "能力與特質 🌟", ex: "Keep your desk clean and books in order.", ex_zh: "保持桌面的整齊乾淨，並把各科課本收拾好。" },
  { id: 537, en: "key", zh: "鑰匙/關鍵", kk: "[ki]", pos: "n.", cat: "日常用品 🎒", ex: "Put your house key safely inside your bag.", ex_zh: "把家裡的鑰匙好好放在書包暗袋裡避免遺失。" },
  { id: 538, en: "kick", zh: "踢", kk: "[kɪk]", pos: "v.", cat: "動作與活動 🏃", ex: "Kick the soccer ball right into the goal.", ex_zh: "起腳把足球漂亮地踢進對方的球門裡面去！" },
  { id: 539, en: "kid", zh: "小孩", kk: "[kɪd]", pos: "n.", cat: "人物與角色 👥", ex: "Kids love running joyfully on the playground.", ex_zh: "小朋友們最喜歡在寬闊的操場上開心地奔跑嬉戲。" },
  { id: 540, en: "kill", zh: "殺死/終結", kk: "[kɪl]", pos: "v.", cat: "動物與自然 🐶", ex: "Never harm or kill little insects for fun.", ex_zh: "絕對不能為了好玩而惡意去傷害或殺死小昆蟲。" },
  { id: 541, en: "kilo", zh: "公斤", kk: "[ˈkilo]", pos: "n.", cat: "數量與代名詞 🔢", ex: "Mom bought one kilo of fresh green apples.", ex_zh: "媽媽在市場採買了一整公斤新鮮甜脆的青蘋果。" },
  { id: 542, en: "kind", zh: "種類/親切的", kk: "[kaɪnd]", pos: "n./adj.", cat: "情緒與特質 😊", ex: "Teacher Pomelo is always gentle and kind.", ex_zh: "柚子老師對待每一位學生總是十分溫柔且親切。" },
  { id: 543, en: "king", zh: "國王", kk: "[kɪŋ]", pos: "n.", cat: "人物與角色 👥", ex: "The brave lion is known as the king of beasts.", ex_zh: "威風凜凜的雄獅在動物界被大家尊稱為百獸之王。" },
  { id: 544, en: "kiss", zh: "吻/親吻", kk: "[kɪs]", pos: "v./n.", cat: "家庭與親友 👨‍👩‍👧", ex: "Mom gives me a sweet goodnight kiss.", ex_zh: "媽媽在睡前輕輕給了我一個充滿關愛的晚安吻。" },
  { id: 545, en: "kitchen", zh: "廚房", kk: "[ˈkɪtʃən]", pos: "n.", cat: "居家與建築 🏡", ex: "Smell the yummy food cooking in the kitchen.", ex_zh: "聞聞看從廚房裡面飄散出來那令人垂涎的飯菜香味。" },
  { id: 546, en: "kite", zh: "風箏", kk: "[kaɪt]", pos: "n.", cat: "日常用品 🎒", ex: "Fly your diamond kite high in the wind.", ex_zh: "趁著涼爽微風把你的菱形風箏高高地放飛天際。" },
  { id: 547, en: "knee", zh: "膝蓋", kk: "[ni]", pos: "n.", cat: "身體與健康 🦵", ex: "Bend your knees slightly when you land.", ex_zh: "跳躍著地的時候記得微微彎曲膝蓋以做好緩衝。" },
  { id: 548, en: "knife", zh: "刀子", kk: "[naɪf]", pos: "n.", cat: "日常用品 🎒", ex: "Be careful when using a fruit knife.", ex_zh: "使用小巧的水果刀切蘋果時一定要特別專心小心。" },
  { id: 549, en: "knock", zh: "敲/敲門", kk: "[nɑk]", pos: "v.", cat: "動作與活動 🏃", ex: "Knock gently on the office door before entering.", ex_zh: "走進教職員辦公室之前，請先禮貌地輕輕敲門。" },
  { id: 550, en: "know", zh: "知道/認識", kk: "[no]", pos: "v.", cat: "動作與思考 🧠", ex: "Do you know the English word for this animal?", ex_zh: "你知道這隻可愛小動物的英文單字該怎麼說嗎？" },
  { id: 551, en: "knowledge", zh: "知識", kk: "[ˈnɑlɪdʒ]", pos: "n.", cat: "學校與學習 📚", ex: "Reading good books brings you rich knowledge.", ex_zh: "閱讀好書能為我們的心靈開拓博大且豐富的知識。" },
  { id: 552, en: "koala", zh: "無尾熊", kk: "[koˈɑlə]", pos: "n.", cat: "動物與自然 🐶", ex: "The lazy koala sleeps on the eucalyptus tree.", ex_zh: "懶洋洋的無尾熊正抱著尤加利樹幹安穩地睡大覺。" },
  { id: 553, en: "lake", zh: "湖泊", kk: "[lek]", pos: "n.", cat: "動物與自然 🐶", ex: "Rowboats float peacefully across the calm lake.", ex_zh: "幾艘划槳小木船悠閒地漂浮在寧靜無波的湖面上。" },
  { id: 554, en: "lamp", zh: "檯燈/燈", kk: "[læmp]", pos: "n.", cat: "日常用品 🎒", ex: "Turn on your desk lamp when reading at night.", ex_zh: "晚上在書桌前看書時記得把書桌檯燈給打開照亮。" },
  { id: 555, en: "land", zh: "土地/降落", kk: "[lænd]", pos: "n./v.", cat: "動物與自然 🐶", ex: "The big airplane landed safely on the runway.", ex_zh: "那架大客機穩穩地、平安順利地降落在機場跑道上。" },
  { id: 556, en: "language", zh: "語言", kk: "[ˈlæŋɡwɪdʒ]", pos: "n.", cat: "學校與學習 📚", ex: "English is a bridge language used worldwide.", ex_zh: "英語是一座連結全世界許多國家文化溝通的橋樑。" },
  { id: 557, en: "lantern", zh: "燈籠", kk: "[ˈlæntɚn]", pos: "n.", cat: "時間與日常 ⏰", ex: "We carry pretty glowing lanterns at Lantern Festival.", ex_zh: "我們在元宵節夜晚提著小巧閃耀的可愛燈籠逛街。" },
  { id: 558, en: "large", zh: "大的", kk: "[lɑrdʒ]", pos: "adj.", cat: "能力與特質 🌟", ex: "Our school has a large and green playground.", ex_zh: "我們學校擁有一座寬闊廣大且鋪滿綠草的運動操場。" },
  { id: 559, en: "last", zh: "最後的/持續", kk: "[læst]", pos: "adj./v.", cat: "時間與日常 ⏰", ex: "December is the last month of the calendar year.", ex_zh: "十二月是一整年日曆當中的最後一個壓軸月份。" },
  { id: 560, en: "late", zh: "晚的/遲到的", kk: "[let]", pos: "adj./adv.", cat: "時間與日常 ⏰", ex: "Go to bed early so you will not be late.", ex_zh: "早睡早起身體好，這樣上學就絕對不會手忙腳亂遲到。" },
  { id: 561, en: "later", zh: "較晚/稍後", kk: "[ˈletɚ]", pos: "adv.", cat: "時間與日常 ⏰", ex: "See you later after our fun English class.", ex_zh: "等一下放學下課之後我們操場見囉，待會兒見！" },
  { id: 562, en: "laugh", zh: "笑/大笑", kk: "[læf]", pos: "v./n.", cat: "情緒與特質 😊", ex: "Kids laugh loudly at the clown's funny tricks.", ex_zh: "小朋友們看著小丑滑稽的魔術動作忍不住哈哈大笑。" },
  { id: 563, en: "lawyer", zh: "律師", kk: "[ˈlɔjɚ]", pos: "n.", cat: "人物與角色 👥", ex: "A lawyer helps people solve legal problems.", ex_zh: "律師用專業的法學素養協助民眾化解法律難題。" },
  { id: 564, en: "lazy", zh: "懶惰的", kk: "[ˈlezi]", pos: "adj.", cat: "情緒與特質 😊", ex: "Don't be lazy; review your five words today.", ex_zh: "不要偷懶放空喔，快把今天的五個單字用心複習好。" },
  { id: 565, en: "lead", zh: "引導/帶領", kk: "[lid]", pos: "v.", cat: "能力與特質 🌟", ex: "Teachers lead us to explore wonderful knowledge.", ex_zh: "老師用心帶領著我們一起去探索奧妙無窮的新知識。" },
  { id: 566, en: "leader", zh: "領導者/隊長", kk: "[ˈlidɚ]", pos: "n.", cat: "人物與角色 👥", ex: "He was chosen as the team leader of our group.", ex_zh: "他在這次小組合作中被推選為盡責可靠的組長。" },
  { id: 567, en: "learn", zh: "學習", kk: "[lɝn]", pos: "v.", cat: "學校與學習 📚", ex: "We learn new things with joy every single day.", ex_zh: "我們每天都在滿滿的求知樂趣中學習全新事物。" },
  { id: 568, en: "least", zh: "最少", kk: "[list]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "Drink at least six cups of water every day.", ex_zh: "每天至少要喝足六杯水，才能維持身體水分平衡。" },
  { id: 569, en: "leave", zh: "離開/留下", kk: "[liv]", pos: "v.", cat: "動作與活動 🏃", ex: "Check your desk items before you leave school.", ex_zh: "在離開校門回家之前，別忘了最後巡視一下桌面。" },
  { id: 570, en: "left", zh: "左邊/向左", kk: "[lɛft]", pos: "n./adj./adv.", cat: "方向與位置 📍", ex: "Turn left at the post office to find the bookstore.", ex_zh: "在郵局路口向左轉，你就能順利看到那家書店了。" },
  { id: 571, en: "leg", zh: "腿", kk: "[lɛɡ]", pos: "n.", cat: "身體與健康 🦵", ex: "Stork birds have very long and slender legs.", ex_zh: "紅鶴與白鷺鷥長著一雙修長又優雅的細腿。" },
  { id: 572, en: "lemon", zh: "檸檬", kk: "[ˈlɛmən]", pos: "n.", cat: "食物與飲品 🍕", ex: "Fresh yellow lemon juice tastes sour and cool.", ex_zh: "現擠的新鮮黃檸檬汁喝起來酸酸涼涼的，非常開胃。" },
  { id: 573, en: "lend", zh: "借出", kk: "[lɛnd]", pos: "v.", cat: "日常表達 💬", ex: "Can you lend me your eraser for a short second?", ex_zh: "可以請你行行好借我擦一下你的橡皮擦嗎？" },
  { id: 574, en: "less", zh: "較少的", kk: "[lɛs]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "Eat less candy and drink more pure water.", ex_zh: "少吃一點糖果點心，多喝一些純淨甘甜的白開水。" },
  { id: 575, en: "lesson", zh: "課/教訓", kk: "[ˈlɛsn]", pos: "n.", cat: "學校與學習 📚", ex: "Listen carefully during today's English lesson.", ex_zh: "在今天這堂精彩的英文課上，請大家務必專注聆聽。" },
  { id: 576, en: "let", zh: "讓/允許", kk: "[lɛt]", pos: "v.", cat: "日常表達 💬", ex: "Let us read this sentence out loud together.", ex_zh: "讓我們全班同學一起把這個生活例句大聲念出來吧。" },
  { id: 577, en: "letter", zh: "信件/字母", kk: "[ˈlɛtɚ]", pos: "n.", cat: "日常用品 🎒", ex: "Write a warm letter to thank your grandparents.", ex_zh: "親筆寫下一封充滿溫暖感恩的信寄給遠方的祖父母。" },
  { id: 578, en: "lettuce", zh: "萵苣/生菜", kk: "[ˈlɛtɪs]", pos: "n.", cat: "食物與飲品 🍕", ex: "Crisp green lettuce is fresh in vegetable salads.", ex_zh: "清脆爽口的綠萵苣是生菜沙拉裡面不可或缺的美味。" },
  { id: 579, en: "library", zh: "圖書館", kk: "[ˈlaɪbrɛri]", pos: "n.", cat: "學校與學習 📚", ex: "We walk quietly and read inside the library.", ex_zh: "走進學校圖書館裡面時請放輕腳步並保持安靜閱讀。" },
  { id: 580, en: "lid", zh: "蓋子", kk: "[lɪd]", pos: "n.", cat: "日常用品 🎒", ex: "Close the water bottle lid tightly after drinking.", ex_zh: "喝完水之後一定要把保溫瓶的蓋子旋轉鎖緊避免漏水。" },
  { id: 581, en: "lie", zh: "說謊/躺臥", kk: "[laɪ]", pos: "v./n.", cat: "動作與思考 🧠", ex: "Good students never tell a lie to their teachers.", ex_zh: "誠實懂事的乖學生絕對不會對老師或父母說謊。" },
  { id: 582, en: "life", zh: "生活/生命", kk: "[laɪf]", pos: "n.", cat: "社會與生活 🏢", ex: "School life is full of bright colors and joy.", ex_zh: "多采多姿的校園生活充滿了滿滿的色彩與歡聲笑語。" },
  { id: 583, en: "light", zh: "燈光/輕的/明亮", kk: "[laɪt]", pos: "n./adj.", cat: "日常用品 🎒", ex: "Turn off the lights when leaving the classroom.", ex_zh: "放學離開教室時記得隨手把日光燈關掉以節約能源。" },
  { id: 584, en: "like", zh: "喜歡/如同", kk: "[laɪk]", pos: "v./prep.", cat: "情緒與特質 😊", ex: "I like solving fun puzzles in English class.", ex_zh: "我好喜歡在英文課的活動中動腦筋解開有趣的謎題。" },
  { id: 585, en: "line", zh: "隊伍/線條", kk: "[laɪn]", pos: "n.", cat: "學校與學習 📚", ex: "Stand in a straight line quietly before lunch.", ex_zh: "午餐抬餐桶前，大家很有規矩地排成一直線隊伍。" },
  { id: 586, en: "lion", zh: "獅子", kk: "[ˈlaɪən]", pos: "n.", cat: "動物與自然 🐶", ex: "The lion roars loudly across the golden valley.", ex_zh: "威猛的獅子對著金黃色的原野發出震耳欲聾的吼叫。" },
  { id: 587, en: "lip", zh: "嘴唇", kk: "[lɪp]", pos: "n.", cat: "身體與健康 🦵", ex: "Drink more water if your lips feel dry.", ex_zh: "如果感覺雙唇乾燥脫皮，記得多補充水分。" },
  { id: 588, en: "list", zh: "表/清單", kk: "[lɪst]", pos: "n./v.", cat: "學校與學習 📚", ex: "Check off items on your study checklist daily.", ex_zh: "每天完成一項功課，就在自己的學習清單上打個勾勾。" },
  { id: 589, en: "listen", zh: "傾聽/聽從", kk: "[ˈlɪsən]", pos: "v.", cat: "動作與思考 🧠", ex: "Listen carefully when other students are sharing.", ex_zh: "當其他同學在台上發言分享時，我們要在底下用心傾聽。" },
  { id: 590, en: "little", zh: "小的/微少", kk: "[ˈlɪtəl]", pos: "adj.", cat: "能力與特質 🌟", ex: "A cute little kitten rests in the sunny corner.", ex_zh: "一隻嬌小可愛的小貓咪正蜷縮在陽光角落舒服歇息。" },
  { id: 591, en: "live", zh: "居住/生活", kk: "[lɪv]", pos: "v.", cat: "社會與生活 🏢", ex: "We live in a friendly and clean neighborhood.", ex_zh: "我們居住在一個充滿鄰里人情味又乾淨和諧的社區。" },
  { id: 592, en: "living room", zh: "客廳", kk: "[ˈlɪvɪŋ rum]", pos: "n.", cat: "居家與建築 🏡", ex: "Our whole family gathers in the warm living room.", ex_zh: "我們全家人吃飽飯後都聚在溫暖舒適的客廳聊天看電視。" },
  { id: 593, en: "lonely", zh: "寂寞的/孤單的", kk: "[ˈlonli]", pos: "adj.", cat: "情緒與特質 😊", ex: "Play with classmates so nobody feels lonely.", ex_zh: "下課主動邀請同學一起玩，這樣就沒有人會感到被孤立冷落了。" },
  { id: 594, en: "long", zh: "長的", kk: "[lɔŋ]", pos: "adj.", cat: "能力與特質 🌟", ex: "An elephant has a remarkably long nose.", ex_zh: "大象長著一條引人注目又靈活有力的大長鼻子。" },
  { id: 595, en: "look", zh: "看/看起來", kk: "[lʊk]", pos: "v.", cat: "動作與思考 🧠", ex: "Look at the colorful blackboard drawing.", ex_zh: "快抬頭看看黑板上那幅五彩繽紛又生動的粉筆畫。" },
  { id: 596, en: "lose", zh: "遺失/輸掉", kk: "[luz]", pos: "v.", cat: "動作與活動 🏃", ex: "Keep your water bottle safe so you don't lose it.", ex_zh: "隨時保管好自己的水瓶，不要一不留神給弄丟了。" },
  { id: 597, en: "loud", zh: "大聲的/響亮的", kk: "[laʊd]", pos: "adj./adv.", cat: "能力與特質 🌟", ex: "Read the English words in a clear and loud voice.", ex_zh: "用清楚明亮又響亮自信的聲音把英文單字給念出來。" },
  { id: 598, en: "love", zh: "喜愛/關愛", kk: "[lʌv]", pos: "v./n.", cat: "情緒與特質 😊", ex: "We love learning new knowledge together every day.", ex_zh: "我們熱愛每天跟好朋友們聚在一起探索滿滿的新知識。" },
  { id: 599, en: "lovely", zh: "可愛的/令人愉快的", kk: "[ˈlʌvli]", pos: "adj.", cat: "情緒與特質 😊", ex: "What a lovely and sunny morning we have today!", ex_zh: "今天早晨的天氣多麼風和日麗、讓人心情愉快啊！" },
  { id: 600, en: "low", zh: "低的/低矮的", kk: "[lo]", pos: "adj./adv.", cat: "能力與特質 🌟", ex: "The small wooden fence around the garden is low.", ex_zh: "圍繞在小花園外圍的那圈白色小木柵欄十分低矮精緻。" }
// ==========================================
  // 第五批（第 601 ~ 750 字）
  // ==========================================
  { id: 601, en: "lucky", zh: "幸運的", kk: "[ˈlʌki]", pos: "adj.", cat: "情緒與特質 😊", ex: "I felt lucky to find my lost pencil.", ex_zh: "能找回遺失的鉛筆，我覺得自己真幸運。" },
  { id: 602, en: "lunch", zh: "午餐", kk: "[lʌntʃ]", pos: "n.", cat: "食物與飲品 🍕", ex: "We enjoy delicious lunch together at twelve.", ex_zh: "我們中午十二點一起享用好吃的午餐。" },
  { id: 603, en: "machine", zh: "機器", kk: "[məˈʃin]", pos: "n.", cat: "日常用品 🎒", ex: "The washing machine cleans our clothes quickly.", ex_zh: "洗衣機能快速地把我們的衣服洗乾淨。" },
  { id: 604, en: "mad", zh: "瘋狂的/生氣的", kk: "[mæd]", pos: "adj.", cat: "情緒與特質 😊", ex: "Don't be mad, let's talk and solve it.", ex_zh: "別生氣，讓我們平靜溝通並解決問題。" },
  { id: 605, en: "magic", zh: "神奇的/魔術", kk: "[ˈmædʒɪk]", pos: "adj./n.", cat: "能力與特質 🌟", ex: "The clown showed us a magic trick.", ex_zh: "小丑為我們表演了一個精彩的神奇魔術。" },
  { id: 606, en: "mail", zh: "信件/郵寄", kk: "[mel]", pos: "n./v.", cat: "日常用品 🎒", ex: "Mom got an important mail from my school.", ex_zh: "媽媽收到了一封學校寄來的重要信件。" },
  { id: 607, en: "mailman", zh: "郵差", kk: "[ˈmelˌmæn]", pos: "n.", cat: "人物與角色 👥", ex: "The friendly mailman brings letters on his bike.", ex_zh: "親切的郵差先生騎著機車為大家送信。" },
  { id: 608, en: "make", zh: "製作/使得", kk: "[mek]", pos: "v.", cat: "動作與活動 🏃", ex: "Let's make a greeting card for our teacher.", ex_zh: "讓我們親手為老師製作一張賀卡吧。" },
  { id: 609, en: "man", zh: "男人", kk: "[mæn]", pos: "n.", cat: "人物與角色 👥", ex: "That tall man is our physical education teacher.", ex_zh: "那位高大的男士是我們的體育老師。" },
  { id: 610, en: "many", zh: "許多的", kk: "[ˈmɛni]", pos: "adj./pron.", cat: "數量與代名詞 🔢", ex: "There are many colorful books on the shelf.", ex_zh: "書架上擺放著好多五顏六色的書本。" },
  { id: 611, en: "map", zh: "地圖", kk: "[mæp]", pos: "n.", cat: "學校與學習 📚", ex: "We found Taiwan on the world map.", ex_zh: "我們在世界地圖上找到了美麗的台灣。" },
  { id: 612, en: "March", zh: "三月", kk: "[mɑrtʃ]", pos: "n.", cat: "時間與日常 ⏰", ex: "Gentle spring flowers bloom in warm March.", ex_zh: "春天溫暖的三月裡，花朵紛紛盛開。" },
  { id: 613, en: "mark", zh: "做記號/痕跡", kk: "[mɑrk]", pos: "v./n.", cat: "學校與學習 📚", ex: "Mark important words with a yellow highlighter.", ex_zh: "用黃色螢光筆在重要單字上做記號。" },
  { id: 614, en: "marker", zh: "簽字筆/彩色筆", kk: "[ˈmɑrkɚ]", pos: "n.", cat: "學校與學習 📚", ex: "Draw your picture with bright color markers.", ex_zh: "用鮮豔的彩色筆畫出你的美麗圖畫。" },
  { id: 615, en: "market", zh: "市場", kk: "[ˈmɑrkɪt]", pos: "n.", cat: "地點與交通 🚌", ex: "Grandma buys fresh fruit at the morning market.", ex_zh: "奶奶早上去傳統市場採買新鮮水果。" },
  { id: 616, en: "married", zh: "已婚的", kk: "[ˈmɛrid]", pos: "adj.", cat: "家庭與親友 👨‍👩‍👧", ex: "My parents have been married for fifteen years.", ex_zh: "我的父母已經結為夫妻十五年了。" },
  { id: 617, en: "mask", zh: "面具/口罩", kk: "[mæsk]", pos: "n.", cat: "衣著與配件 👕", ex: "Wear a mask when you have a cough.", ex_zh: "咳嗽或感冒時記得戴上口罩保護大家。" },
  { id: 618, en: "mat", zh: "墊子", kk: "[mæt]", pos: "n.", cat: "日常用品 🎒", ex: "Wipe your shoes on the door mat.", ex_zh: "進門前先在門口的踏墊上把鞋底擦乾淨。" },
  { id: 619, en: "math", zh: "數學", kk: "[mæθ]", pos: "n.", cat: "學校與學習 📚", ex: "We solve interesting number puzzles in math.", ex_zh: "我們在數學課上解開有趣的數字謎題。" },
  { id: 620, en: "matter", zh: "事情/有關係", kk: "[ˈmætɚ]", pos: "n./v.", cat: "日常表達 💬", ex: "What is the matter? Can I help you?", ex_zh: "怎麼了呢？需要我幫忙你嗎？" },
  { id: 621, en: "may", zh: "可以/可能", kk: "[me]", pos: "aux.", cat: "能力與特質 🌟", ex: "May I drink some water, please?", ex_zh: "老師，請問我可以喝點水嗎？" },
  { id: 622, en: "May", zh: "五月", kk: "[me]", pos: "n.", cat: "時間與日常 ⏰", ex: "Mother's Day is celebrated in May.", ex_zh: "我們在溫馨的五月慶祝母親節。" },
  { id: 623, en: "maybe", zh: "也許", kk: "[ˈmebi]", pos: "adv.", cat: "日常表達 💬", ex: "Maybe we can play basketball after school.", ex_zh: "也許我們放學後可以一起打籃球。" },
  { id: 624, en: "meal", zh: "一餐", kk: "[mil]", pos: "n.", cat: "食物與飲品 🍕", ex: "Breakfast is the most important meal of a day.", ex_zh: "早餐是一整天當中最重要的一餐。" },
  { id: 625, en: "mean", zh: "意指/刻薄的", kk: "[min]", pos: "v./adj.", cat: "日常表達 💬", ex: "What does this new English word mean?", ex_zh: "這個全新的英文單字代表什麼意思呢？" },
  { id: 626, en: "meat", zh: "肉類", kk: "[mit]", pos: "n.", cat: "食物與飲品 🍕", ex: "Eat both vegetables and meat for balance.", ex_zh: "蔬菜與肉類都要均衡攝取才健康。" },
  { id: 627, en: "medicine", zh: "藥物", kk: "[ˈmɛdɪsn]", pos: "n.", cat: "身體與健康 🦵", ex: "Take your medicine on time to get well.", ex_zh: "按時吃藥才能讓身體快點康復喔。" },
  { id: 628, en: "medium", zh: "中號/中等的", kk: "[ˈmidɪəm]", pos: "adj./n.", cat: "數量與代名詞 🔢", ex: "I ordered a medium cup of warm milk.", ex_zh: "我點了一杯中杯的溫熱牛奶。" },
  { id: 629, en: "meet", zh: "遇見/碰面", kk: "[mit]", pos: "v.", cat: "動作與活動 🏃", ex: "Nice to meet you in our new classroom.", ex_zh: "很高興在我們的新教室裡遇見你。" },
  { id: 630, en: "meeting", zh: "會議/集會", kk: "[ˈmitɪŋ]", pos: "n.", cat: "社會與生活 🏢", ex: "Teachers are having a morning meeting.", ex_zh: "老師們正在會議室裡開晨會。" },
  { id: 631, en: "menu", zh: "菜單", kk: "[ˈmɛnju]", pos: "n.", cat: "日常用品 🎒", ex: "Let's read the menu and pick our lunch.", ex_zh: "我們一起看看菜單挑選想吃的午餐吧。" },
  { id: 632, en: "mile", zh: "哩/英里", kk: "[maɪl]", pos: "n.", cat: "數量與代名詞 🔢", ex: "We walked one mile along the riverside.", ex_zh: "我們沿著河岸步道整整走了一英里。" },
  { id: 633, en: "milk", zh: "牛奶", kk: "[mɪlk]", pos: "n.", cat: "食物與飲品 🍕", ex: "Drink a cup of fresh milk every morning.", ex_zh: "每天早晨喝一杯香濃的新鮮牛奶。" },
  { id: 634, en: "million", zh: "百萬", kk: "[ˈmɪljən]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Millions of stars shine in the quiet night sky.", ex_zh: "數百萬顆閃爍的星星點綴著寧靜夜空。" },
  { id: 635, en: "mind", zh: "介意/心思", kk: "[maɪnd]", pos: "v./n.", cat: "動作與思考 🧠", ex: "Do you mind if I sit beside you?", ex_zh: "你介意我坐在你的身旁嗎？" },
  { id: 636, en: "minute", zh: "分鐘", kk: "[ˈmɪnɪt]", pos: "n.", cat: "時間與日常 ⏰", ex: "Wait for just one minute, please.", ex_zh: "請在原地稍等我一分鐘就好。" },
  { id: 637, en: "Miss", zh: "小姐/女教師", kk: "[mɪs]", pos: "n.", cat: "人物與角色 👥", ex: "Miss Lin teaches us wonderful music lessons.", ex_zh: "林老師為我們帶來精采動聽的音樂課。" },
  { id: 638, en: "miss", zh: "想念/錯過", kk: "[mɪs]", pos: "v.", cat: "情緒與特質 😊", ex: "I miss my classmates during the long vacation.", ex_zh: "長假期間我好想念班上的各位同學。" },
  { id: 639, en: "mistake", zh: "錯誤", kk: "[mɪˈstek]", pos: "n.", cat: "學校與學習 📚", ex: "We learn and grow from our mistakes.", ex_zh: "我們都能從犯過的錯誤中學習成長。" },
  { id: 640, en: "modern", zh: "現代化的", kk: "[ˈmɑdɚn]", pos: "adj.", cat: "能力與特質 🌟", ex: "Our computer room is very modern and neat.", ex_zh: "我們的電腦教室非常現代化且整潔。" },
  { id: 641, en: "moment", zh: "片刻/瞬間", kk: "[ˈmomənt]", pos: "n.", cat: "時間與日常 ⏰", ex: "Wait a moment, I will pack my bag quickly.", ex_zh: "等我片刻，我馬上把書包整理好。" },
  { id: 642, en: "Monday", zh: "星期一", kk: "[ˈmʌnde]", pos: "n.", cat: "時間與日常 ⏰", ex: "Monday is the start of a brand-new school week.", ex_zh: "星期一代表著全新上學週的起點。" },
  { id: 643, en: "money", zh: "錢", kk: "[ˈmʌni]", pos: "n.", cat: "日常用品 🎒", ex: "Save your pocket money in a piggy bank.", ex_zh: "把零用錢存進你的小豬撲滿裡。" },
  { id: 644, en: "monkey", zh: "猴子", kk: "[ˈmʌŋki]", pos: "n.", cat: "動物與自然 🐶", ex: "The playful monkey swings between green branches.", ex_zh: "活潑的猴子在翠綠的樹枝間靈活擺盪。" },
  { id: 645, en: "month", zh: "月份", kk: "[mʌnθ]", pos: "n.", cat: "時間與日常 ⏰", ex: "There are twelve months in one year.", ex_zh: "一年之中總共有十二個月份。" },
  { id: 646, en: "moon", zh: "月亮", kk: "[mun]", pos: "n.", cat: "動物與自然 🐶", ex: "The round full moon shines bright tonight.", ex_zh: "圓圓的滿月今晚在夜空中散發柔和光芒。" },
  { id: 647, en: "mop", zh: "拖地/拖把", kk: "[mɑp]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Let's mop the floor clean after lunch.", ex_zh: "吃完午餐後，讓我們一起把地板拖乾淨。" },
  { id: 648, en: "more", zh: "更多的", kk: "[mɔr]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "Read more books to gain wonderful knowledge.", ex_zh: "多讀好書，能獲取豐富廣博的新知識。" },
  { id: 649, en: "morning", zh: "早上/早晨", kk: "[ˈmɔrnɪŋ]", pos: "n.", cat: "時間與日常 ⏰", ex: "Good morning! Are you ready to learn?", ex_zh: "大家早安！準備好一起開心學習了嗎？" },
  { id: 650, en: "most", zh: "大多數的", kk: "[most]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "Most students like playing tag at recess.", ex_zh: "大多數同學都喜歡在下課時間玩抓人遊戲。" },
  { id: 651, en: "mother", zh: "母親", kk: "[ˈmʌðɚ]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "My mother gives me a warm and loving hug.", ex_zh: "我的母親給了我一個充滿溫暖與愛的擁抱。" },
  { id: 652, en: "motorcycle", zh: "機車/摩托車", kk: "[ˈmotɚˌsaɪkəl]", pos: "n.", cat: "交通工具 🚗", ex: "Wear a helmet when riding on a motorcycle.", ex_zh: "搭乘機車時一定要確實戴好安全帽。" },
  { id: 653, en: "mountain", zh: "山", kk: "[ˈmaʊntən]", pos: "n.", cat: "動物與自然 🐶", ex: "We hiked up the green mountain on Sunday.", ex_zh: "我們在星期天登上了青翠的高山。" },
  { id: 654, en: "mouse", zh: "老鼠/滑鼠", kk: "[maʊs]", pos: "n.", cat: "動物與自然 🐶", ex: "Click the computer mouse to select answers.", ex_zh: "點擊電腦滑鼠來選取正確答案。" },
  { id: 655, en: "mouth", zh: "嘴巴", kk: "[maʊθ]", pos: "n.", cat: "身體與健康 🦵", ex: "Cover your mouth when you sneeze or cough.", ex_zh: "打噴嚏或咳嗽時記得遮住嘴巴。" },
  { id: 656, en: "move", zh: "移動/搬動", kk: "[muv]", pos: "v.", cat: "動作與活動 🏃", ex: "Move your chair quietly so others can study.", ex_zh: "輕輕搬動椅子，讓大家能安靜學習。" },
  { id: 657, en: "movie", zh: "電影", kk: "[ˈmuvi]", pos: "n.", cat: "社會與生活 🏢", ex: "We watched a funny animal movie together.", ex_zh: "我們全家一起看了一部有趣的動物電影。" },
  { id: 658, en: "Mr.", zh: "先生", kk: "[ˈmɪstɚ]", pos: "n.", cat: "人物與角色 👥", ex: "Mr. Wang is our kind science teacher.", ex_zh: "王先生是我們親切又風趣的自然科學老師。" },
  { id: 659, en: "Mrs.", zh: "太太", kk: "[ˈmɪsɪz]", pos: "n.", cat: "人物與角色 👥", ex: "Mrs. Chen prepared sweet cookies for everyone.", ex_zh: "陳太太貼心地為大家烤了甜甜的餅乾。" },
  { id: 660, en: "MRT", zh: "捷運", kk: "[ˌɛm ɑr ˈti]", pos: "n.", cat: "交通工具 🚗", ex: "Taking the MRT is clean, fast, and safe.", ex_zh: "搭乘捷運既乾淨、快速又十分安全。" },
  { id: 661, en: "Ms.", zh: "女士", kk: "[mɪz]", pos: "n.", cat: "人物與角色 👥", ex: "Ms. Chang leads the school singing club.", ex_zh: "張女士指導帶領著學校的合唱社團。" },
  { id: 662, en: "much", zh: "許多的", kk: "[mʌtʃ]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "Thank you very much for your kind help.", ex_zh: "非常感謝你給予的貼心與熱情幫忙。" },
  { id: 663, en: "mud", zh: "泥巴", kk: "[mʌd]", pos: "n.", cat: "動物與自然 🐶", ex: "Little pigs roll joyfully in cool mud.", ex_zh: "小豬在涼涼的泥巴坑裡開心地打滾。" },
  { id: 664, en: "museum", zh: "博物館", kk: "[mjuˈziəm]", pos: "n.", cat: "地點與交通 🚌", ex: "We saw big dinosaur bones at the museum.", ex_zh: "我們在博物館裡看到了巨大的恐龍化石骨骼。" },
  { id: 665, en: "music", zh: "音樂", kk: "[ˈmjuzɪk]", pos: "n.", cat: "學校與學習 📚", ex: "Listening to soft music makes me feel calm.", ex_zh: "聆聽柔和的音樂能讓心情感到平靜放鬆。" },
  { id: 666, en: "must", zh: "必須", kk: "[mʌst]", pos: "aux.", cat: "能力與特質 🌟", ex: "We must listen when our teacher is talking.", ex_zh: "當老師在說話時，我們必須專心聆聽。" },
  { id: 667, en: "nail", zh: "釘子/指甲", kk: "[nel]", pos: "n.", cat: "日常用品 🎒", ex: "Keep your fingernails clean and short.", ex_zh: "定期修剪手指甲，保持乾淨衛生。" },
  { id: 668, en: "name", zh: "名字", kk: "[nem]", pos: "n.", cat: "學校與學習 📚", ex: "Write your English name at the top of the paper.", ex_zh: "把你的英文名字寫在測驗紙的最上方。" },
  { id: 669, en: "national", zh: "國家的/全國的", kk: "[ˈnæʃənəl]", pos: "adj.", cat: "地點與空間 🗺️", ex: "We visited the national park on our vacation.", ex_zh: "我們在假期時參觀了景色壯麗的國家公園。" },
  { id: 670, en: "near", zh: "在…附近", kk: "[nɪr]", pos: "prep./adj.", cat: "方向與位置 📍", ex: "The bookstore is near our elementary school.", ex_zh: "那家文具書店就在我們小學的附近。" },
  { id: 671, en: "neck", zh: "脖子", kk: "[nɛk]", pos: "n.", cat: "身體與健康 🦵", ex: "Giraffes have remarkably long necks.", ex_zh: "長頸鹿擁有非常長且優雅的長脖子。" },
  { id: 672, en: "need", zh: "需要", kk: "[nid]", pos: "v./n.", cat: "能力與特質 🌟", ex: "You need a pencil and an eraser for class.", ex_zh: "上課時你需要準備好鉛筆和橡皮擦。" },
  { id: 673, en: "neighbor", zh: "鄰居", kk: "[ˈnebɚ]", pos: "n.", cat: "人物與角色 👥", ex: "Our neighbors are very kind and friendly.", ex_zh: "我們的鄰居非常親切和善，相處融洽。" },
  { id: 674, en: "never", zh: "從不", kk: "[ˈnɛvɚ]", pos: "adv.", cat: "時間與日常 ⏰", ex: "Never cross the street when the light is red.", ex_zh: "紅燈亮起時，絕對不可以穿越馬路。" },
  { id: 675, en: "new", zh: "新的", kk: "[nju]", pos: "adj.", cat: "能力與特質 🌟", ex: "I have a new water bottle for school.", ex_zh: "我換了一個全新的水瓶帶來學校喝水。" },
  { id: 676, en: "news", zh: "消息/新聞", kk: "[njuz]", pos: "n.", cat: "社會與生活 🏢", ex: "I have wonderful news to share with everyone!", ex_zh: "我有一個天大的好消息要跟全班分享！" },
  { id: 677, en: "next", zh: "下一個/接下來", kk: "[nɛkst]", pos: "adj./adv.", cat: "時間與日常 ⏰", ex: "Who is the next student to read aloud?", ex_zh: "接下來輪到哪一位同學起立大聲念例句呢？" },
  { id: 678, en: "nice", zh: "好的/友善的", kk: "[naɪs]", pos: "adj.", cat: "情緒與特質 😊", ex: "Have a nice and cheerful weekend!", ex_zh: "祝你有個美好愉快又充滿歡笑的週末！" },
  { id: 679, en: "night", zh: "晚上/夜晚", kk: "[naɪt]", pos: "n.", cat: "時間與日常 ⏰", ex: "Say good night to mom before sleeping.", ex_zh: "睡覺之前跟媽媽說聲溫馨的晚安。" },
  { id: 680, en: "nine", zh: "九", kk: "[naɪn]", pos: "num.", cat: "數量與代名詞 🔢", ex: "We go to sleep around nine o'clock at night.", ex_zh: "我們晚上大約九點左右準時上床睡覺。" },
  { id: 681, en: "nineteen", zh: "十九", kk: "[ˌnaɪnˈtin]", pos: "num.", cat: "數量與代名詞 🔢", ex: "There are nineteen boys in this sports team.", ex_zh: "這支運動代表隊裡總共有十九名男同學。" },
  { id: 682, en: "nineteenth", zh: "第十九", kk: "[ˌnaɪnˈtinθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Today is the nineteenth day of the month.", ex_zh: "今天是這個月份的第十九天。" },
  { id: 683, en: "ninety", zh: "九十", kk: "[ˈnaɪnti]", pos: "num.", cat: "數量與代名詞 🔢", ex: "He scored ninety points on his English quiz.", ex_zh: "他在這次英文小考中拿到了九十分的好成績。" },
  { id: 684, en: "ninth", zh: "第九", kk: "[naɪnθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "September is the ninth month of the year.", ex_zh: "九月是一整年當中的第九個月份。" },
  { id: 685, en: "no", zh: "沒有/不是", kk: "[no]", pos: "adj./adv.", cat: "日常表達 💬", ex: "There is no doubt you can do this well.", ex_zh: "毫無疑問，你一定能把這件事做得很好。" },
  { id: 686, en: "nobody", zh: "無一人", kk: "[ˈnobədi]", pos: "pron.", cat: "人物與角色 👥", ex: "Nobody likes being left out of games.", ex_zh: "沒有人喜歡在玩遊戲時被單獨冷落在一旁。" },
  { id: 687, en: "nod", zh: "點頭", kk: "[nɑd]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Nod your head with a smile to say yes.", ex_zh: "帶著微笑點點頭，表示贊成與同意。" },
  { id: 688, en: "noise", zh: "噪音", kk: "[nɔɪz]", pos: "n.", cat: "日常用品 🎒", ex: "Do not make loud noise inside the library.", ex_zh: "在圖書館內請放輕音量，不要製造噪音。" },
  { id: 689, en: "noodle", zh: "麵條", kk: "[ˈnudəl]", pos: "n.", cat: "食物與飲品 🍕", ex: "A hot bowl of noodles warms us up.", ex_zh: "一碗熱騰騰的現煮湯麵讓全身都暖和起來。" },
  { id: 690, en: "noon", zh: "中午", kk: "[nun]", pos: "n.", cat: "時間與日常 ⏰", ex: "The school bell rings for lunch at noon.", ex_zh: "中午十二點整，下課吃午餐的鐘聲準時響起。" },
  { id: 691, en: "north", zh: "北方", kk: "[nɔrθ]", pos: "n./adj.", cat: "方向與位置 📍", ex: "The compass needle points directly north.", ex_zh: "指南針上的指針筆直地指向北方。" },
  { id: 692, en: "nose", zh: "鼻子", kk: "[noz]", pos: "n.", cat: "身體與健康 🦵", ex: "Elephants have long and strong noses.", ex_zh: "大象長著一隻強健有力又長長的大鼻子。" },
  { id: 693, en: "not", zh: "不/未", kk: "[nɑt]", pos: "adv.", cat: "日常表達 💬", ex: "Do not worry; practice makes perfect.", ex_zh: "不要擔心，熟能生巧，多練就會了。" },
  { id: 694, en: "note", zh: "筆記/便條", kk: "[not]", pos: "n./v.", cat: "學校與學習 📚", ex: "Take good notes during your English class.", ex_zh: "上英文課時要在筆記本上做好重點紀錄。" },
  { id: 695, en: "notebook", zh: "筆記本", kk: "[ˈnotˌbʊk]", pos: "n.", cat: "學校與學習 📚", ex: "Write five words in your notebook daily.", ex_zh: "每天在專用筆記本上練習寫下五個新單字。" },
  { id: 696, en: "nothing", zh: "沒什麼/無事", kk: "[ˈnʌθɪŋ]", pos: "pron.", cat: "日常表達 💬", ex: "There is nothing better than playing with friends.", ex_zh: "沒有任何事比跟好朋友聚在一起玩更快樂了。" },
  { id: 697, en: "notice", zh: "注意到/公告", kk: "[ˈnotɪs]", pos: "v./n.", cat: "動作與思考 🧠", ex: "Did you notice the colorful butterflies in the garden?", ex_zh: "你有注意到花園裡翩翩飛舞的花蝴蝶嗎？" },
  { id: 698, en: "November", zh: "十一月", kk: "[noˈvɛmbɚ]", pos: "n.", cat: "時間與日常 ⏰", ex: "The cool autumn wind arrives in November.", ex_zh: "十一月帶來了涼爽宜人的陣陣秋風。" },
  { id: 699, en: "now", zh: "現在", kk: "[naʊ]", pos: "adv.", cat: "時間與日常 ⏰", ex: "Open your books to page ten right now.", ex_zh: "現在立刻將課本翻到第十頁。" },
  { id: 700, en: "number", zh: "號碼/數字", kk: "[ˈnʌmbɚ]", pos: "n.", cat: "數量與代名詞 🔢", ex: "Seven is my lucky number.", ex_zh: "數字七是我心目中最幸運的號碼。" },
  { id: 701, en: "nurse", zh: "護士/護理師", kk: "[nɝs]", pos: "n.", cat: "人物與角色 👥", ex: "The school nurse cared for my scraped knee.", ex_zh: "學校健康中心的護理師細心幫我的擦傷擦藥。" },
  { id: 702, en: "o' clock", zh: "點鐘", kk: "[əˈklɑk]", pos: "adv.", cat: "時間與日常 ⏰", ex: "We start morning reading at eight o'clock.", ex_zh: "我們在早上八點整準時展開晨讀活動。" },
  { id: 703, en: "October", zh: "十月", kk: "[ɑkˈtobɚ]", pos: "n.", cat: "時間與日常 ⏰", ex: "Halloween is celebrated on the last day of October.", ex_zh: "萬聖節就在十月的最後一天開心地度過。" },
  { id: 704, en: "of", zh: "...的", kk: "[əv]", pos: "prep.", cat: "日常表達 💬", ex: "This is a photo of our happy family.", ex_zh: "這張是我們全家人充滿歡樂氣氛的合照。" },
  { id: 705, en: "off", zh: "自……離開/關閉", kk: "[ɔf]", pos: "prep./adv.", cat: "日常表達 💬", ex: "Turn off the lights when leaving the room.", ex_zh: "離開教室之前，別忘了隨手把日光燈關閉。" },
  { id: 706, en: "office", zh: "辦公室", kk: "[ˈɔfɪs]", pos: "n.", cat: "學校與學習 📚", ex: "Teachers prepare interesting lessons in the office.", ex_zh: "老師們在辦公室裡用心為大家備課。" },
  { id: 707, en: "officer", zh: "警官/官員", kk: "[ˈɔfɪsɚ]", pos: "n.", cat: "人物與角色 👥", ex: "The police officer guides kids across the road.", ex_zh: "交通警官在路口守護小朋友安全過馬路。" },
  { id: 708, en: "often", zh: "時常/常常", kk: "[ˈɔfən]", pos: "adv.", cat: "時間與日常 ⏰", ex: "We often play basketball after school.", ex_zh: "放學之後，我們常常相約一起打籃球。" },
  { id: 709, en: "oil", zh: "食用油/石油", kk: "[ɔɪl]", pos: "n.", cat: "食物與飲品 🍕", ex: "Mom uses a little olive oil to fry eggs.", ex_zh: "媽媽用少許天然橄欖油為我們煎蛋。" },
  { id: 710, en: "OK", zh: "可以/好的", kk: "[oˈke]", pos: "adj./adv.", cat: "日常表達 💬", ex: "Are you feeling OK today?", ex_zh: "你今天身體感覺還好嗎？一切都順利嗎？" },
  { id: 711, en: "old", zh: "老的/舊的", kk: "[old]", pos: "adj.", cat: "能力與特質 🌟", ex: "The ancient banyan tree in our school is very old.", ex_zh: "我們校園裡那棵枝葉茂盛的老榕樹年紀很大了。" },
  { id: 712, en: "on", zh: "在……上面", kk: "[ɑn]", pos: "prep.", cat: "方向與位置 📍", ex: "Put your pencil neatly on the desk.", ex_zh: "把你的鉛筆整齊地擺放在書桌上面。" },
  { id: 713, en: "once", zh: "一次/曾經", kk: "[wʌns]", pos: "adv.", cat: "時間與日常 ⏰", ex: "Review your words at least once a day.", ex_zh: "每天至少把學過的新單字認真溫習一次。" },
  { id: 714, en: "one", zh: "一/一個人", kk: "[wʌn]", pos: "num./pron.", cat: "數量與代名詞 🔢", ex: "One step at a time leads to big success.", ex_zh: "一步一腳印踏實前進，就能累積成大成功。" },
  { id: 715, en: "only", zh: "只有/僅僅", kk: "[ˈonli]", pos: "adj./adv.", cat: "數量與代名詞 🔢", ex: "There is only one apple left in the fruit bowl.", ex_zh: "水果碗裡目前只剩下最後一顆紅蘋果了。" },
  { id: 716, en: "open", zh: "打開/營業中", kk: "[ˈopən]", pos: "v./adj.", cat: "動作與活動 🏃", ex: "Open your English textbook to page twenty.", ex_zh: "請大家把英文課本翻開到第二十頁。" },
  { id: 717, en: "or", zh: "或者", kk: "[ɔr]", pos: "conj.", cat: "日常表達 💬", ex: "Do you want apple juice or milk?", ex_zh: "你想喝香甜的蘋果汁，還是營養的牛奶呢？" },
  { id: 718, en: "orange", zh: "柳橙/橘色(的)", kk: "[ˈɔrɪndʒ]", pos: "n./adj.", cat: "食物與飲品 🍕", ex: "Peel the sweet orange and share with friends.", ex_zh: "剝開這顆甜甜的柳橙，跟好朋友一起分享吧。" },
  { id: 719, en: "order", zh: "點餐/順序", kk: "[ˈɔrdɚ]", pos: "v./n.", cat: "社會與生活 🏢", ex: "Keep your books in neat alphabetical order.", ex_zh: "依照字母順序把故事書整齊排列好。" },
  { id: 720, en: "other", zh: "其他的", kk: "[ˈʌðɚ]", pos: "adj./pron.", cat: "數量與代名詞 🔢", ex: "Be kind and considerate to other people.", ex_zh: "對待身邊的其他同學要友善且有同理心。" },
  { id: 721, en: "out", zh: "在外/出外", kk: "[aʊt]", pos: "adv.", cat: "方向與位置 📍", ex: "Look out the window at the sunny blue sky.", ex_zh: "向窗外看過去，欣賞陽光明媚的蔚藍天空。" },
  { id: 722, en: "outside", zh: "在...外面", kk: "[ˌaʊtˈsaɪd]", pos: "prep./adv.", cat: "方向與位置 📍", ex: "Let's play dodge ball outside on the court.", ex_zh: "讓我們到外面的球場上一同暢快打球吧。" },
  { id: 723, en: "over", zh: "結束/在…上方", kk: "[ˈovɚ]", pos: "prep./adv.", cat: "時間與日常 ⏰", ex: "Class is over; have a wonderful recess time!", ex_zh: "這節課下課了，祝大家有個開心充實的休息時間！" },
  { id: 724, en: "own", zh: "自己的/擁有", kk: "[on]", pos: "adj./v.", cat: "能力與特質 🌟", ex: "Pack your own school bag every single evening.", ex_zh: "每天晚上都要自己動手把書包收拾齊全。" },
  { id: 725, en: "ox", zh: "公牛", kk: "[ɑks]", pos: "n.", cat: "動物與自然 🐶", ex: "The strong ox helps plow the farmland.", ex_zh: "強壯沉穩的耕牛在農田裡協助農夫耕作。" },
  { id: 726, en: "pack", zh: "打包/包裝", kk: "[pæk]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Pack your water bottle before you leave for school.", ex_zh: "出門上學前，記得把裝滿水的水瓶放好。" },
  { id: 727, en: "package", zh: "包裹", kk: "[ˈpækɪdʒ]", pos: "n.", cat: "日常用品 🎒", ex: "The delivery man brought a package to our door.", ex_zh: "送貨員送來了一個精緻的大包裹到家門口。" },
  { id: 728, en: "page", zh: "頁面", kk: "[pedʒ]", pos: "n.", cat: "學校與學習 📚", ex: "Turn the page carefully so you don't tear it.", ex_zh: "小心翻動書頁，不要不小心把它撕破了。" },
  { id: 729, en: "paint", zh: "繪畫/顏料", kk: "[pent]", pos: "v./n.", cat: "學校與學習 📚", ex: "Paint the sky blue with your watercolor brush.", ex_zh: "用水彩筆將畫紙上的天空塗上明亮的蔚藍色。" },
  { id: 730, en: "pair", zh: "一雙/一對", kk: "[pɛr]", pos: "n.", cat: "數量與代名詞 🔢", ex: "I have a new pair of comfortable running shoes.", ex_zh: "我有一雙穿起來非常舒適的新慢跑鞋。" },
  { id: 731, en: "pants", zh: "長褲", kk: "[pænts]", pos: "n.", cat: "衣著與配件 👕", ex: "Wear long pants to protect your legs when hiking.", ex_zh: "登山健行時穿著長褲能保護雙腿不被草木劃傷。" },
  { id: 732, en: "papaya", zh: "木瓜", kk: "[pəˈpaɪə]", pos: "n.", cat: "食物與飲品 🍕", ex: "Fresh papaya milk is a popular drink in Taiwan.", ex_zh: "新鮮現打的木瓜牛奶是台灣非常受歡迎的特色飲品。" },
  { id: 733, en: "paper", zh: "紙張", kk: "[ˈpepɚ]", pos: "n.", cat: "學校與學習 📚", ex: "Draw a colorful picture on this sheet of paper.", ex_zh: "在這張潔白的紙上畫出一幅色彩繽紛的圖畫吧。" },
  { id: 734, en: "parent", zh: "父(母)親/雙親", kk: "[ˈpɛrənt]", pos: "n.", cat: "家庭與親友 👨‍👩‍👧", ex: "Show this permission slip to your parents.", ex_zh: "把這張校外教學通知單帶回家拿給父母簽名。" },
  { id: 735, en: "park", zh: "公園/停放", kk: "[pɑrk]", pos: "n./v.", cat: "地點與交通 🚌", ex: "Kids ride bicycles safely inside the park.", ex_zh: "小朋友們在公園專用道上安全地騎腳踏車。" },
  { id: 736, en: "part", zh: "部分/零件", kk: "[pɑrt]", pos: "n.", cat: "日常表達 💬", ex: "Reading is an important part of our daily life.", ex_zh: "閱讀是我們日常生活當中非常重要的一部分。" },
  { id: 737, en: "party", zh: "派對/聚會", kk: "[ˈpɑrti]", pos: "n.", cat: "社會與生活 🏢", ex: "We sang and played games at the birthday party.", ex_zh: "我們在生日派對上一同歡唱並玩著有趣的遊戲。" },
  { id: 738, en: "pass", zh: "通過/遞給", kk: "[pæs]", pos: "v.", cat: "動作與活動 🏃", ex: "Pass the ball quickly to your teammate.", ex_zh: "迅速把球傳遞給場上的隊友以創造得分機會。" },
  { id: 739, en: "past", zh: "經過/過去的", kk: "[pæst]", pos: "prep./adj.", cat: "時間與日常 ⏰", ex: "It is ten minutes past eight right now.", ex_zh: "現在的時間是早上八點過十分。" },
  { id: 740, en: "paste", zh: "黏貼/漿糊", kk: "[pest]", pos: "v./n.", cat: "學校與學習 📚", ex: "Paste the cutout shapes on your art project.", ex_zh: "把剪下來的圖形工整黏貼在你的美勞作品上。" },
  { id: 741, en: "pay", zh: "付錢/薪水", kk: "[pe]", pos: "v./n.", cat: "社會與生活 🏢", ex: "Pay attention in class to learn efficiently.", ex_zh: "上課時專心注意聽講，學習效率才會高。" },
  { id: 742, en: "PE", zh: "體育課", kk: "[ˌpi ˈi]", pos: "n.", cat: "體育與運動 🏅", ex: "We do warm-up exercises together in PE class.", ex_zh: "我們在體育課一開始跟著老師一起認真做熱身操。" },
  { id: 743, en: "peach", zh: "桃子", kk: "[pitʃ]", pos: "n.", cat: "食物與飲品 🍕", ex: "Juicy peaches taste sweet and soft in summer.", ex_zh: "夏天多汁的水蜜桃吃起來口感香甜又細嫩。" },
  { id: 744, en: "pear", zh: "梨子", kk: "[pɛr]", pos: "n.", cat: "食物與飲品 🍕", ex: "The fresh green pear is crunchy and sweet.", ex_zh: "這顆新鮮的青梨吃起來既爽脆又甘甜解渴。" },
  { id: 745, en: "pen", zh: "原子筆/鋼筆", kk: "[pɛn]", pos: "n.", cat: "學校與學習 📚", ex: "Write your answers neatly with a blue pen.", ex_zh: "用深藍色原子筆把答案整齊工整地寫下來。" },
  { id: 746, en: "pencil", zh: "鉛筆", kk: "[ˈpɛnsəl]", pos: "n.", cat: "學校與學習 📚", ex: "Sharpen your pencil before the test starts.", ex_zh: "考試開始前，先把鉛筆削得尖尖好寫。" },
  { id: 747, en: "people", zh: "人們", kk: "[ˈpipəl]", pos: "n.", cat: "人物與角色 👥", ex: "Kind people make the world a warmer place.", ex_zh: "善良的人們讓這個世界處處充滿溫暖與愛。" },
  { id: 748, en: "perhaps", zh: "或許/大概", kk: "[pɚˈhæps]", pos: "adv.", cat: "日常表達 💬", ex: "Perhaps we will visit the science museum tomorrow.", ex_zh: "或許我們明天可以安排參觀自然科學博物館。" },
  { id: 749, en: "person", zh: "人/個人", kk: "[ˈpɝsn]", pos: "n.", cat: "人物與角色 👥", ex: "Be a polite and responsible person every day.", ex_zh: "在日常生活中成為一個既有禮貌又有責任感的人。" },
  { id: 750, en: "pet", zh: "寵物", kk: "[pɛt]", pos: "n.", cat: "動物與自然 🐶", ex: "Take loving care of your pet dog at home.", ex_zh: "用愛心細心照顧陪伴家中的毛小孩寵物犬。" }
// ==========================================
  // 第六批（第 751 ~ 900 字）
  // ==========================================
  { id: 751, en: "photo", zh: "相片", kk: "[ˈfoto]", pos: "n.", cat: "日常用品 🎒", ex: "Dad took a lovely photo of our family.", ex_zh: "爸爸為我們全家拍了一張溫馨的相片。" },
  { id: 752, en: "piano", zh: "鋼琴", kk: "[pɪˈæno]", pos: "n.", cat: "學校與學習 📚", ex: "She plays gentle melodies on the piano.", ex_zh: "她在鋼琴上彈奏出優美輕柔的旋律。" },
  { id: 753, en: "pick", zh: "撿拾/挑選", kk: "[pɪk]", pos: "v.", cat: "動作與活動 🏃", ex: "Pick up the litter to keep our classroom clean.", ex_zh: "隨手把垃圾撿起來，保持教室乾淨整潔。" },
  { id: 754, en: "picnic", zh: "野餐", kk: "[ˈpɪknɪk]", pos: "n./v.", cat: "體育與運動 🏅", ex: "We had a sunny picnic in the green park.", ex_zh: "我們在陽光明媚的綠意公園裡開心野餐。" },
  { id: 755, en: "picture", zh: "圖片/相片", kk: "[ˈpɪktʃɚ]", pos: "n.", cat: "學校與學習 📚", ex: "Draw a colorful picture with your markers.", ex_zh: "用你的彩色筆畫出一幅色彩繽紛的圖畫。" },
  { id: 756, en: "pie", zh: "派", kk: "[paɪ]", pos: "n.", cat: "食物與飲品 🍕", ex: "Grandma baked an apple pie for dessert.", ex_zh: "奶奶烤了香甜的蘋果派當作課後甜點。" },
  { id: 757, en: "piece", zh: "片/塊/張", kk: "[pis]", pos: "n.", cat: "數量與代名詞 🔢", ex: "May I have a piece of paper, please?", ex_zh: "請問我可以借一張白紙來寫字嗎？" },
  { id: 758, en: "pig", zh: "豬", kk: "[pɪɡ]", pos: "n.", cat: "動物與自然 🐶", ex: "The pink pig rolls joyfully in the cool mud.", ex_zh: "粉紅小豬在涼爽的泥巴裡開心地打滾。" },
  { id: 759, en: "pin", zh: "大頭針/別針", kk: "[pɪn]", pos: "n.", cat: "學校與學習 📚", ex: "Pin the poster neatly on the bulletin board.", ex_zh: "把海報用大頭針工整地別在佈告欄上。" },
  { id: 760, en: "pink", zh: "粉紅色(的)", kk: "[pɪŋk]", pos: "adj./n.", cat: "色彩與形狀 🎨", ex: "Cherry blossoms in spring look sweet and pink.", ex_zh: "春天的櫻花盛開，看起來粉嫩又甜美。" },
  { id: 761, en: "pipe", zh: "管子/水管", kk: "[paɪp]", pos: "n.", cat: "日常用品 🎒", ex: "Water flows smoothly through the garden pipe.", ex_zh: "水流順暢地流過花園裡的澆水水管。" },
  { id: 762, en: "pizza", zh: "披薩", kk: "[ˈpitsə]", pos: "n.", cat: "食物與飲品 🍕", ex: "Let's share this warm cheese pizza together.", ex_zh: "我們大家一起分享這份熱騰騰的起司披薩吧。" },
  { id: 763, en: "place", zh: "地方/放置", kk: "[ples]", pos: "n./v.", cat: "地點與空間 🗺️", ex: "Our classroom is a wonderful place to learn.", ex_zh: "我們的教室是一個充滿歡笑與探索的好地方。" },
  { id: 764, en: "plan", zh: "計畫", kk: "[plæn]", pos: "n./v.", cat: "動作與思考 🧠", ex: "Make a good study plan for your test.", ex_zh: "為即將到來的考試制定一個良好的讀書計畫。" },
  { id: 765, en: "planet", zh: "行星", kk: "[ˈplænɪt]", pos: "n.", cat: "動物與自然 🐶", ex: "Earth is the only planet with water and life.", ex_zh: "地球是目前已知唯一孕育生命與水源的行星。" },
  { id: 766, en: "plant", zh: "植物/種植", kk: "[plænt]", pos: "n./v.", cat: "動物與自然 🐶", ex: "Water the green plants in our class garden.", ex_zh: "記得給班級小花圃裡的綠色植物澆澆水。" },
  { id: 767, en: "plate", zh: "盤子", kk: "[plet]", pos: "n.", cat: "日常用品 🎒", ex: "Put the sliced apples neatly on the plate.", ex_zh: "把切好的蘋果片整齊地排放在盤子裡。" },
  { id: 768, en: "play", zh: "玩耍/彈奏", kk: "[ple]", pos: "v.", cat: "動作與活動 🏃", ex: "Kids play games happily during recess.", ex_zh: "下課時間小朋友們開心地在走廊玩遊戲。" },
  { id: 769, en: "player", zh: "選手/球員", kk: "[ˈpleɚ]", pos: "n.", cat: "人物與角色 👥", ex: "He is the best basketball player in our team.", ex_zh: "他是我們代表隊裡投籃最準的籃球選手。" },
  { id: 770, en: "playground", zh: "操場/遊樂場", kk: "[ˈpleˌɡraʊnd]", pos: "n.", cat: "學校與學習 📚", ex: "We run and play tag on the wide playground.", ex_zh: "我們在寬敞的操場上快跑並玩抓人遊戲。" },
  { id: 771, en: "pleasure", zh: "樂事/榮幸", kk: "[ˈplɛʒɚ]", pos: "n.", cat: "情緒與特質 😊", ex: "It is my pleasure to help you with math.", ex_zh: "能教你解開這道數學題是我的榮幸。" },
  { id: 772, en: "please", zh: "請/使高興", kk: "[pliz]", pos: "interj./v.", cat: "日常表達 💬", ex: "Please raise your hand before speaking out.", ex_zh: "想要發言回答問題前，請先記得舉手喔。" },
  { id: 773, en: "p.m.", zh: "下午/晚上", kk: "[ˈpiˈɛm]", pos: "adv.", cat: "時間與日常 ⏰", ex: "School finishes at four p.m. every day.", ex_zh: "學校每天在下午四點準時放學。" },
  { id: 774, en: "pocket", zh: "口袋", kk: "[ˈpɑkɪt]", pos: "n.", cat: "衣著與配件 👕", ex: "Keep your bus card safely in your jacket pocket.", ex_zh: "把公車卡好好收在外套的口袋裡避免掉落。" },
  { id: 775, en: "point", zh: "指著/分數", kk: "[pɔɪnt]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Point to the correct word on the blackboard.", ex_zh: "用手指指出黑板上寫的那一個正確單字。" },
  { id: 776, en: "police", zh: "警察(方)", kk: "[pəˈlis]", pos: "n.", cat: "人物與角色 👥", ex: "The police work hard to keep our city safe.", ex_zh: "警察辛勤巡邏，守護著我們城市的治安與安全。" },
  { id: 777, en: "polite", zh: "有禮貌的", kk: "[pəˈlaɪt]", pos: "adj.", cat: "情緒與特質 😊", ex: "Always say thank you and be a polite student.", ex_zh: "常把謝謝掛嘴邊，做一個知書達禮的乖學生。" },
  { id: 778, en: "pond", zh: "池塘", kk: "[pɑnd]", pos: "n.", cat: "動物與自然 🐶", ex: "Frogs leap and fish swim in the school pond.", ex_zh: "小青蛙跳躍、金魚在校園生態池塘裡悠游。" },
  { id: 779, en: "pool", zh: "游泳池", kk: "[pul]", pos: "n.", cat: "體育與運動 🏅", ex: "We take cool swimming lessons in the pool.", ex_zh: "夏天我們在學校游泳池裡上清涼的游泳課。" },
  { id: 780, en: "poor", zh: "貧困的/可憐的", kk: "[pʊr]", pos: "adj.", cat: "情緒與特質 😊", ex: "Help poor animals find a warm home.", ex_zh: "發揮愛心，協助流浪動物找到溫暖的家。" },
  { id: 781, en: "popcorn", zh: "爆米花", kk: "[ˈpɑpˌkɔrn]", pos: "n.", cat: "食物與飲品 🍕", ex: "Warm popcorn smells sweet at the movie theater.", ex_zh: "電影院裡剛出爐的香甜爆米花聞起來真誘人。" },
  { id: 782, en: "popular", zh: "受歡迎的", kk: "[ˈpɑpjəlɚ]", pos: "adj.", cat: "人物與角色 👥", ex: "Dodge ball is very popular among kids.", ex_zh: "躲避球運動在國小學生之間非常受到歡迎。" },
  { id: 783, en: "pork", zh: "豬肉", kk: "[pɔrk]", pos: "n.", cat: "食物與飲品 🍕", ex: "Steamed pork buns are warm and juicy.", ex_zh: "剛蒸好的豬肉包子吃起來熱騰騰又多汁。" },
  { id: 784, en: "possible", zh: "可能的", kk: "[ˈpɑsəbəl]", pos: "adj.", cat: "日常表達 💬", ex: "Try your best; anything is possible!", ex_zh: "全力以赴嘗試吧，萬事皆有可能成真！" },
  { id: 785, en: "post office", zh: "郵局", kk: "[post ˈɔfɪs]", pos: "n.", cat: "地點與交通 🚌", ex: "Mail your thank-you letter at the post office.", ex_zh: "到郵局把這封滿懷感恩的信件寄出去。" },
  { id: 786, en: "postcard", zh: "明信片", kk: "[ˈpostˌkɑrd]", pos: "n.", cat: "日常用品 🎒", ex: "I sent a pretty postcard to my best friend.", ex_zh: "我寄了一張風景美麗的明信片給我最好的朋友。" },
  { id: 787, en: "pot", zh: "罐/鍋子", kk: "[pɑt]", pos: "n.", cat: "日常用品 🎒", ex: "Mom cooks hot vegetable soup in a big pot.", ex_zh: "媽媽用一個大鍋子熬煮香濃的蔬菜湯。" },
  { id: 788, en: "pound", zh: "磅(重量單位)", kk: "[paʊnd]", pos: "n.", cat: "數量與代名詞 🔢", ex: "Dad bought three pounds of sweet oranges.", ex_zh: "爸爸在水果行買了整整三磅的香甜柳橙。" },
  { id: 789, en: "practice", zh: "練習", kk: "[ˈpræktɪs]", pos: "v./n.", cat: "學校與學習 📚", ex: "Practice every day to speak English well.", ex_zh: "每天持續練習，就能把英語說得流利自然。" },
  { id: 790, en: "pray", zh: "祈禱", kk: "[pre]", pos: "v.", cat: "動作與思考 🧠", ex: "We pray for peace, health, and happiness.", ex_zh: "我們默默祈禱大家都平平安安、健康快樂。" },
  { id: 791, en: "prepare", zh: "準備", kk: "[prɪˈpɛr]", pos: "v.", cat: "動作與活動 🏃", ex: "Prepare your textbook and pencils for class.", ex_zh: "把上課要用到的課本和鉛筆事先準備好。" },
  { id: 792, en: "present", zh: "禮物/現在的", kk: "[ˈprɛznt]", pos: "n./adj.", cat: "日常用品 🎒", ex: "I wrapped a birthday present for my friend.", ex_zh: "我用心包裝了一份生日禮物要送給好朋友。" },
  { id: 793, en: "pretty", zh: "漂亮的/相當", kk: "[ˈprɪti]", pos: "adj./adv.", cat: "情緒與特質 😊", ex: "The yellow dress you wear looks very pretty.", ex_zh: "你今天穿的這件黃色洋裝看起來真漂亮。" },
  { id: 794, en: "price", zh: "價格", kk: "[praɪs]", pos: "n.", cat: "日常用品 🎒", ex: "The price of this colorful notebook is low.", ex_zh: "這本彩色筆記本的售價既便宜又划算。" },
  { id: 795, en: "princess", zh: "公主", kk: "[ˈprɪnsɪs]", pos: "n.", cat: "人物與角色 👥", ex: "The kind princess helped animals in the forest.", ex_zh: "善良的公主在森林裡幫助了許多小動物。" },
  { id: 796, en: "prize", zh: "獎品/獎項", kk: "[praɪz]", pos: "n.", cat: "學校與學習 📚", ex: "He won first prize in the English speech contest.", ex_zh: "他在英語演講比賽中勇奪了第一名的殊榮。" },
  { id: 797, en: "problem", zh: "問題/難題", kk: "[ˈprɑbləm]", pos: "n.", cat: "學校與學習 📚", ex: "Ask teacher if you have any math problems.", ex_zh: "如果在數學上有遇到不懂的問題，隨時可以問老師。" },
  { id: 798, en: "program", zh: "節目/程式", kk: "[ˈproɡræm]", pos: "n.", cat: "社會與生活 🏢", ex: "We watched an educational science program.", ex_zh: "我們觀看了一段富有教育意義的科普節目。" },
  { id: 799, en: "proud", zh: "驕傲的/引以為榮", kk: "[praʊd]", pos: "adj.", cat: "情緒與特質 😊", ex: "Teacher is proud of your great effort.", ex_zh: "老師對你認真付出的努力感到非常驕傲。" },
  { id: 800, en: "public", zh: "公立的/公眾的", kk: "[ˈpʌblɪk]", pos: "adj./n.", cat: "地點與空間 🗺️", ex: "Keep quiet when you read in the public library.", ex_zh: "在公共圖書館看書時請保持安靜。" },
  { id: 801, en: "pull", zh: "拉/拖", kk: "[pʊl]", pos: "v.", cat: "動作與活動 🏃", ex: "Pull the classroom door open gently.", ex_zh: "請輕輕地把教室的大門往外拉開。" },
  { id: 802, en: "pumpkin", zh: "南瓜", kk: "[ˈpʌmpkɪn]", pos: "n.", cat: "食物與飲品 🍕", ex: "We carve orange pumpkins for Halloween.", ex_zh: "萬聖節時我們動手雕刻大橘南瓜燈。" },
  { id: 803, en: "purple", zh: "紫色的", kk: "[ˈpɝpəl]", pos: "adj./n.", cat: "色彩與形狀 🎨", ex: "Juicy grapes on the plate look deep purple.", ex_zh: "盤子裡的鮮甜葡萄呈現美麗的深紫色。" },
  { id: 804, en: "push", zh: "推", kk: "[pʊʃ]", pos: "v.", cat: "動作與活動 🏃", ex: "Never push others when walking in hallway lines.", ex_zh: "排隊走在走廊上時，絕對不可以互相推擠。" },
  { id: 805, en: "put", zh: "放/放置", kk: "[pʊt]", pos: "v.", cat: "動作與活動 🏃", ex: "Put your books neatly into your school bag.", ex_zh: "把你的課本整齊地收納進書包裡面。" },
  { id: 806, en: "quarter", zh: "一刻鐘(15分鐘)/四分之一", kk: "[ˈkwɔrtɚ]", pos: "n.", cat: "時間與日常 ⏰", ex: "It is a quarter past eight right now.", ex_zh: "現在的時間正好是八點十五分。" },
  { id: 807, en: "queen", zh: "皇后", kk: "[kwin]", pos: "n.", cat: "人物與角色 👥", ex: "The wise queen loved everyone in her country.", ex_zh: "睿智的皇后深愛著全國每一位百姓。" },
  { id: 808, en: "question", zh: "問題/疑問", kk: "[ˈkwɛstʃən]", pos: "n.", cat: "學校與學習 📚", ex: "Raise your hand if you have a question.", ex_zh: "如果對單字意思有任何問題，請隨時舉手。" },
  { id: 809, en: "quick", zh: "迅速的/快的", kk: "[kwɪk]", pos: "adj.", cat: "能力與特質 🌟", ex: "Take a quick look at today's five words.", ex_zh: "快速看一眼今天精選的五個全新單字吧。" },
  { id: 810, en: "quiet", zh: "安靜的", kk: "[ˈkwaɪət]", pos: "adj.", cat: "情緒與特質 😊", ex: "Please be quiet while reading in the library.", ex_zh: "在圖書館閱覽時請務必保持安靜不說話。" },
  { id: 811, en: "quite", zh: "相當/十分", kk: "[kwaɪt]", pos: "adv.", cat: "日常表達 💬", ex: "Today's cloze quiz is quite interesting.", ex_zh: "今天的克漏字填空挑戰相當生動有趣。" },
  { id: 812, en: "quiz", zh: "小考/測驗", kk: "[kwɪz]", pos: "n.", cat: "學校與學習 📚", ex: "We take a fun vocabulary quiz every morning.", ex_zh: "我們每天早晨都會做一次好玩的單字小測驗。" },
  { id: 813, en: "rabbit", zh: "兔子", kk: "[ˈræbɪt]", pos: "n.", cat: "動物與自然 🐶", ex: "The white rabbit has long ears and pink eyes.", ex_zh: "小白兔有一對長長的耳朵和粉紅色的眼睛。" },
  { id: 814, en: "race", zh: "賽跑/競賽", kk: "[res]", pos: "n./v.", cat: "體育與運動 🏅", ex: "He won the one-hundred-meter running race.", ex_zh: "他在一百公尺短跑競賽中勇奪第一名。" },
  { id: 815, en: "radio", zh: "收音機/廣播", kk: "[ˈredɪˌo]", pos: "n.", cat: "日常用品 🎒", ex: "Grandpa listens to morning news on the radio.", ex_zh: "爺爺習慣一早打開收音機收聽晨間廣播新聞。" },
  { id: 816, en: "railroad", zh: "鐵路", kk: "[ˈrelˌrod]", pos: "n.", cat: "地點與交通 🚌", ex: "Wait behind the white line near the railroad.", ex_zh: "在鐵路平交道旁時要在白線後方等候。" },
  { id: 817, en: "rain", zh: "下雨/雨水", kk: "[ren]", pos: "v./n.", cat: "時間與天氣 ☀️", ex: "Take an umbrella because it may rain today.", ex_zh: "帶把傘出門吧，因為今天外頭可能會下雨。" },
  { id: 818, en: "rainbow", zh: "彩虹", kk: "[ˈrenˌbo]", pos: "n.", cat: "時間與天氣 ☀️", ex: "A seven-color rainbow appears after the storm.", ex_zh: "雷雨過後，空中出現了一道七彩美麗的彩虹。" },
  { id: 819, en: "rainy", zh: "下雨的/多雨的", kk: "[ˈreni]", pos: "adj.", cat: "時間與天氣 ☀️", ex: "We play indoor board games on rainy days.", ex_zh: "下雨天時我們就改在室內玩桌遊。" },
  { id: 820, en: "raise", zh: "舉起/撫養", kk: "[rez]", pos: "v.", cat: "動作與活動 🏃", ex: "Raise your right hand to answer the question.", ex_zh: "想要回答問題的同學請舉起你的右手。" },
  { id: 821, en: "rat", zh: "老鼠/大鼠", kk: "[ræt]", pos: "n.", cat: "動物與自然 🐶", ex: "The cat chased the sneaking rat away.", ex_zh: "機警的貓咪把那隻偷偷摸摸的大老鼠趕跑了。" },
  { id: 822, en: "read", zh: "閱讀/朗讀", kk: "[rid]", pos: "v.", cat: "學校與學習 📚", ex: "Read five English sentences out loud daily.", ex_zh: "每天把五句英文生活例句大聲念出來。" },
  { id: 823, en: "ready", zh: "準備好的", kk: "[ˈrɛdi]", pos: "adj.", cat: "能力與特質 🌟", ex: "Are you ready for our fun English lesson?", ex_zh: "大家準備好迎接有趣的英文學習了嗎？" },
  { id: 824, en: "real", zh: "真的/真實的", kk: "[riəl]", pos: "adj.", cat: "日常表達 💬", ex: "True friends give each other real support.", ex_zh: "真正的摯友會給予彼此最真實的鼓勵與支持。" },
  { id: 825, en: "really", zh: "真地/確實", kk: "[ˈriəli]", pos: "adv.", cat: "日常表達 💬", ex: "You did really well on this word challenge!", ex_zh: "你在這次單字大挑戰中表現得真的很出色！" },
  { id: 826, en: "recorder", zh: "直笛/錄音機", kk: "[rɪˈkɔrdɚ]", pos: "n.", cat: "學校與學習 📚", ex: "We play sweet tunes on our recorders in music class.", ex_zh: "我們在音樂課上用直笛吹奏出美妙動聽的曲調。" },
  { id: 827, en: "red", zh: "紅色(的)", kk: "[rɛd]", pos: "adj./n.", cat: "色彩與形狀 🎨", ex: "Red apples on the table taste sweet and fresh.", ex_zh: "桌上鮮紅的蘋果吃起來既香甜又清脆。" },
  { id: 828, en: "refrigerator", zh: "冰箱", kk: "[rɪˈfrɪdʒəˌretɚ]", pos: "n.", cat: "日常用品 🎒", ex: "Keep fresh milk inside the refrigerator.", ex_zh: "把鮮奶放進冰箱冷藏室保鮮。" },
  { id: 829, en: "remember", zh: "記得/牢記", kk: "[rɪˈmɛmbɚ]", pos: "v.", cat: "動作與思考 🧠", ex: "Remember to do your five words every day.", ex_zh: "別忘了每天都要牢記這五個精選英文單字。" },
  { id: 830, en: "repeat", zh: "重複", kk: "[rɪˈpit]", pos: "v.", cat: "學校與學習 📚", ex: "Listen and repeat the words after the teacher.", ex_zh: "仔細聆聽，然後跟著老師把單字大聲重複一遍。" },
  { id: 831, en: "reporter", zh: "記者", kk: "[rɪˈpɔrtɚ]", pos: "n.", cat: "人物與角色 👥", ex: "The campus reporter interviewed our soccer team.", ex_zh: "校園小記者今天採訪了剛獲勝的足球隊。" },
  { id: 832, en: "rest", zh: "休息/其餘", kk: "[rɛst]", pos: "v./n.", cat: "時間與日常 ⏰", ex: "Take a ten-minute rest to protect your eyes.", ex_zh: "下課休息十分鐘，好好保護眼睛健康。" },
  { id: 833, en: "restaurant", zh: "餐館/餐廳", kk: "[ˈrɛstərənt]", pos: "n.", cat: "地點與交通 🚌", ex: "Our family had dinner at an Italian restaurant.", ex_zh: "我們全家在一間義大利餐廳享用美味晚餐。" },
  { id: 834, en: "restroom", zh: "洗手間/廁所", kk: "[ˈrɛstrum]", pos: "n.", cat: "學校與學習 📚", ex: "Wash your hands clean after using the restroom.", ex_zh: "上完洗手間後記得把雙手確實洗乾淨。" },
  { id: 835, en: "rice", zh: "米飯", kk: "[raɪs]", pos: "n.", cat: "食物與飲品 🍕", ex: "We enjoy warm rice and fresh vegetables.", ex_zh: "我們享用熱騰騰的白米飯配美味蔬菜。" },
  { id: 836, en: "rich", zh: "有錢的/豐富的", kk: "[rɪtʃ]", pos: "adj.", cat: "能力與特質 🌟", ex: "Good story books are rich in wonderful ideas.", ex_zh: "優秀的故事書蘊含著豐富深刻的啟發點子。" },
  { id: 837, en: "ride", zh: "騎/乘車", kk: "[raɪd]", pos: "v./n.", cat: "動作與活動 🏃", ex: "I ride my bicycle to school every morning.", ex_zh: "我每天清晨都騎著腳踏車上學。" },
  { id: 838, en: "right", zh: "右方/正確的", kk: "[raɪt]", pos: "n./adj.", cat: "方向與位置 📍", ex: "Turn right at the bookstore corner.", ex_zh: "在文具書店的路口轉角向右轉。" },
  { id: 839, en: "ring", zh: "戒指/按鈴", kk: "[rɪŋ]", pos: "n./v.", cat: "衣著與配件 👕", ex: "Listen! The school bell starts to ring.", ex_zh: "快聽！下課的歡樂鐘聲已經開始響起了。" },
  { id: 840, en: "river", zh: "河川/河流", kk: "[ˈrɪvɚ]", pos: "n.", cat: "動物與自然 🐶", ex: "Clear river water flows gently down the green hill.", ex_zh: "清澈的河水緩緩從小山丘上流過。" },
  { id: 841, en: "road", zh: "道路/馬路", kk: "[rod]", pos: "n.", cat: "地點與交通 🚌", ex: "Look both ways before you walk across the road.", ex_zh: "穿越馬路前，一定要先左右看清楚路況。" },
  { id: 842, en: "robot", zh: "機器人", kk: "[ˈrobɑt]", pos: "n.", cat: "學校與學習 📚", ex: "We built a clever little robot in science club.", ex_zh: "我們在自然科學社團親手組裝了一台小機器人。" },
  { id: 843, en: "ROC", zh: "中華民國", kk: "[ˌɑr o ˈsi]", pos: "n.", cat: "地點與空間 🗺️", ex: "Our country is the ROC, Taiwan.", ex_zh: "我們的國家是中華民國（台灣）。" },
  { id: 844, en: "rock", zh: "岩石/搖動", kk: "[rɑk]", pos: "n./v.", cat: "動物與自然 🐶", ex: "A small lizard rests on the sunny rock.", ex_zh: "一隻小蜥蜴停留在溫暖的岩石上曬太陽。" },
  { id: 845, en: "roll", zh: "滾動/卷", kk: "[rol]", pos: "v./n.", cat: "動作與活動 🏃", ex: "Roll the ball gently across the gym floor.", ex_zh: "把球輕輕地在體育館的地板上滾動過去。" },
  { id: 846, en: "room", zh: "房間/空間", kk: "[rum]", pos: "n.", cat: "居家與建築 🏡", ex: "Keep your bedroom neat and tidy.", ex_zh: "把自己的臥室打掃得乾乾淨淨、井然有序。" },
  { id: 847, en: "roller-skate", zh: "溜冰/四輪溜冰", kk: "[ˈrolɚˌsket]", pos: "v./n.", cat: "體育與運動 🏅", ex: "We roller-skate safely wearing helmets in the park.", ex_zh: "我們戴好安全帽在公園裡開心地溜四輪溜冰鞋。" },
  { id: 848, en: "rope", zh: "繩子", kk: "[rop]", pos: "n.", cat: "日常用品 🎒", ex: "Skipping rope is a great sport for your health.", ex_zh: "跳繩是一項非常鍛鍊身體與心肺的有益運動。" },
  { id: 849, en: "rose", zh: "玫瑰花", kk: "[roz]", pos: "n.", cat: "動物與自然 🐶", ex: "Red roses bloom beautifully in the spring garden.", ex_zh: "紅玫瑰在春天的花園裡美麗綻放。" },
  { id: 850, en: "round", zh: "圓形的/循環", kk: "[raʊnd]", pos: "adj./n.", cat: "色彩與形狀 🎨", ex: "Soccer balls are round and easy to kick.", ex_zh: "足球是圓形的，非常適合在草地上踢球射門。" },
  { id: 851, en: "row", zh: "划(船)/一排", kk: "[ro]", pos: "v./n.", cat: "動作與活動 🏃", ex: "We row the boat gently across the lake.", ex_zh: "我們划著小船，輕快地在清澈的湖面上滑行。" },
  { id: 852, en: "rule", zh: "規則", kk: "[rul]", pos: "n.", cat: "學校與學習 📚", ex: "Always follow the classroom rules politely.", ex_zh: "在班級裡大家都要遵守共同的班規。" },
  { id: 853, en: "ruler", zh: "尺", kk: "[ˈrulɚ]", pos: "n.", cat: "學校與學習 📚", ex: "Use a ruler to draw a straight line.", ex_zh: "用直尺畫出一條平整筆直的直線。" },
  { id: 854, en: "run", zh: "跑", kk: "[rʌn]", pos: "v.", cat: "動作與活動 🏃", ex: "Kids run fast across the green track.", ex_zh: "小朋友們在操場的綠色跑道上飛快奔跑。" },
  { id: 855, en: "sad", zh: "悲傷的/難過的", kk: "[sæd]", pos: "adj.", cat: "情緒與特質 😊", ex: "Don't be sad; we are always here for you.", ex_zh: "不要難過，我們好朋友永遠都在你身邊支持你。" },
  { id: 856, en: "safe", zh: "安全的", kk: "[sef]", pos: "adj.", cat: "能力與特質 🌟", ex: "Look both sides to stay safe on streets.", ex_zh: "過馬路時左右張望，確保自身安全。" },
  { id: 857, en: "sail", zh: "航行/帆", kk: "[sel]", pos: "v./n.", cat: "動作與活動 🏃", ex: "White sailboats sail smoothly on the blue sea.", ex_zh: "白色帆船在蔚藍的海面上順風航行。" },
  { id: 858, en: "salad", zh: "沙拉", kk: "[ˈsæləd]", pos: "n.", cat: "食物與飲品 🍕", ex: "Fresh vegetable salad is good for your health.", ex_zh: "新鮮清爽的蔬菜沙拉對身體健康十分有益。" },
  { id: 859, en: "sale", zh: "出售/特價", kk: "[sel]", pos: "n.", cat: "社會與生活 🏢", ex: "Storybooks are on sale at the bookstore today.", ex_zh: "書店裡的故事書今天剛好有特價折扣活動。" },
  { id: 860, en: "salesman", zh: "推銷員/男售貨員", kk: "[ˈselzmən]", pos: "n.", cat: "人物與角色 👥", ex: "The polite salesman introduced the new bicycle.", ex_zh: "親切有禮的店員為我們詳細介紹這台新腳踏車。" },
  { id: 861, en: "salt", zh: "鹽", kk: "[sɔlt]", pos: "n.", cat: "食物與飲品 🍕", ex: "Add just a little salt to the tomato soup.", ex_zh: "在番茄湯裡加入少許鹽巴提味就好。" },
  { id: 862, en: "same", zh: "相同的", kk: "[sem]", pos: "adj.", cat: "日常表達 💬", ex: "We wear the same neat school uniform.", ex_zh: "我們穿著整齊劃一的同款校服。" },
  { id: 863, en: "sandwich", zh: "三明治", kk: "[ˈsænwɪtʃ]", pos: "n.", cat: "食物與飲品 🍕", ex: "Mom made an egg sandwich for my breakfast.", ex_zh: "媽媽早餐為我親手做了一份好吃的蛋三明治。" },
  { id: 864, en: "Saturday", zh: "星期六", kk: "[ˈsætɚˌde]", pos: "n.", cat: "時間與日常 ⏰", ex: "We play baseball together every Saturday morning.", ex_zh: "每週六早晨我們都會相約一起去打棒球。" },
  { id: 865, en: "sacred", zh: "神聖的/莊嚴的", kk: "[ˈsekrɪd]", pos: "adj.", cat: "能力與特質 🌟", ex: "Keep quiet inside sacred temples and churches.", ex_zh: "走進莊嚴神聖的寺廟與教堂時要保持肅靜。" },
  { id: 866, en: "save", zh: "節省/拯救", kk: "[sev]", pos: "v.", cat: "動作與思考 🧠", ex: "Save water and turn off the tap tightly.", ex_zh: "節約用水，洗完手後請把水龍頭旋緊。" },
  { id: 867, en: "say", zh: "說/說話", kk: "[se]", pos: "v.", cat: "日常表達 💬", ex: "Say good morning politely to everyone.", ex_zh: "每天看見師長同學都要親切地說聲早安。" },
  { id: 868, en: "school", zh: "學校", kk: "[skul]", pos: "n.", cat: "學校與學習 📚", ex: "We enjoy learning new knowledge at school.", ex_zh: "我們在學校裡開心地探索與汲取新知識。" },
  { id: 869, en: "science", zh: "科學", kk: "[ˈsaɪəns]", pos: "n.", cat: "學校與學習 📚", ex: "We do fun hands-on experiments in science class.", ex_zh: "我們在自然科學課上動手做許多有趣的實驗。" },
  { id: 870, en: "scooter", zh: "速克達機車/滑板車", kk: "[ˈskutɚ]", pos: "n.", cat: "交通工具 🚗", ex: "Kids ride kick scooters on park trails.", ex_zh: "小朋友們在公園專用步道上開心地騎滑板車。" },
  { id: 871, en: "screen", zh: "螢幕", kk: "[skrin]", pos: "n.", cat: "日常用品 🎒", ex: "Rest your eyes away from the computer screen.", ex_zh: "看一陣子電腦螢幕後，記得讓眼睛望向遠方休息。" },
  { id: 872, en: "sea", zh: "海/海洋", kk: "[si]", pos: "n.", cat: "動物與自然 🐶", ex: "Dolphins jump high in the deep blue sea.", ex_zh: "海豚在蔚藍的大海中歡樂地躍出水面。" },
  { id: 873, en: "season", zh: "季節", kk: "[ˈsizn]", pos: "n.", cat: "時間與天氣 ☀️", ex: "Spring is a warm and colorful season.", ex_zh: "春天是一個充滿溫暖陽光與繁花盛開的季節。" },
  { id: 874, en: "seat", zh: "座位", kk: "[sit]", pos: "n.", cat: "日常用品 🎒", ex: "Please return to your seat and sit quietly.", ex_zh: "上課鐘響了，請大家迅速回到座位安靜坐好。" },
  { id: 875, en: "second", zh: "第二/秒", kk: "[ˈsɛkənd]", pos: "num./n.", cat: "數量與代名詞 🔢", ex: "Wait for just a second, I will help you.", ex_zh: "請稍等我一秒鐘，我馬上過來協助你。" },
  { id: 876, en: "secretary", zh: "秘書", kk: "[ˈsɛkrəˌtɛri]", pos: "n.", cat: "人物與角色 👥", ex: "The school secretary answers phone calls politely.", ex_zh: "學校幹事秘書有禮貌地接聽各方家長來電。" },
  { id: 877, en: "see", zh: "看見/明白", kk: "[si]", pos: "v.", cat: "動作與思考 🧠", ex: "I can see white clouds floating in the sky.", ex_zh: "我能看見悠悠白雲在天空中慢慢飄動。" },
  { id: 878, en: "seed", zh: "種子", kk: "[sid]", pos: "n.", cat: "動物與自然 🐶", ex: "Plant a sunflower seed in the garden pot.", ex_zh: "把向日葵的小種子種進花盆泥土裡。" },
  { id: 879, en: "seesaw", zh: "蹺蹺板", kk: "[ˈsiˌsɔ]", pos: "n.", cat: "體育與運動 🏅", ex: "Two friends play on the seesaw happily.", ex_zh: "兩個好朋友在遊戲區一上一下高興地玩蹺蹺板。" },
  { id: 880, en: "seldom", zh: "很少/不常", kk: "[ˈsɛldəm]", pos: "adv.", cat: "時間與日常 ⏰", ex: "It seldom snows in the flatlands of Taiwan.", ex_zh: "在台灣平地區域幾乎很少有下雪的機會。" },
  { id: 881, en: "sell", zh: "賣/出售", kk: "[sɛl]", pos: "v.", cat: "社會與生活 🏢", ex: "They sell fresh bread and warm milk here.", ex_zh: "這家商店販賣新鮮剛出爐的麵包與熱牛奶。" },
  { id: 882, en: "send", zh: "寄出/派遣", kk: "[sɛnd]", pos: "v.", cat: "動作與活動 🏃", ex: "Send an email to say happy birthday to your friend.", ex_zh: "寄一封電子郵件祝你的好朋友生日快樂。" },
  { id: 883, en: "senior high school", zh: "高中", kk: "[ˈsinjɚ haɪ skul]", pos: "n.", cat: "學校與學習 📚", ex: "My older brother studies hard in senior high school.", ex_zh: "我的哥哥在高中裡認真用功地準備升學。" },
  { id: 884, en: "sentence", zh: "句子", kk: "[ˈsɛntəns]", pos: "n.", cat: "學校與學習 📚", ex: "Read this English sentence out loud clearly.", ex_zh: "請把這個英文生活例句清楚明亮地念出來。" },
  { id: 885, en: "September", zh: "九月", kk: "[sɛpˈtɛmbɚ]", pos: "n.", cat: "時間與日常 ⏰", ex: "The new school semester begins in September.", ex_zh: "全新的上學期在秋高氣爽的九月份正式開始。" },
  { id: 886, en: "serious", zh: "嚴肅的/嚴重的", kk: "[ˈsɪriəs]", pos: "adj.", cat: "情緒與特質 😊", ex: "Be serious when doing science experiments.", ex_zh: "做自然科學實驗時態度一定要嚴肅專注以策安全。" },
  { id: 887, en: "set", zh: "(電視)機/一套/放置", kk: "[sɛt]", pos: "n./v.", cat: "日常用品 🎒", ex: "Dad bought a new color pencil set for me.", ex_zh: "爸爸買了一整套全新的十二色彩色鉛筆送我。" },
  { id: 888, en: "seven", zh: "七", kk: "[ˈsɛvən]", pos: "num.", cat: "數量與代名詞 🔢", ex: "There are seven days in every single week.", ex_zh: "每一個星期裡面都包含著完整的七天。" },
  { id: 889, en: "seventeen", zh: "十七", kk: "[ˌsɛvənˈtin]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Seventeen students joined the sports club.", ex_zh: "總共有十七名同學報名參加了學校體育社團。" },
  { id: 890, en: "seventeenth", zh: "第十七", kk: "[ˌsɛvənˈtinθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Today is the seventeenth day of the month.", ex_zh: "今天是這個月份的第十七天。" },
  { id: 891, en: "seventh", zh: "第七", kk: "[ˈsɛvənθ]", pos: "num.", cat: "數量與代名詞 🔢", ex: "July is the seventh month of a year.", ex_zh: "七月是一整年當中的第七個月份。" },
  { id: 892, en: "seventy", zh: "七十", kk: "[ˈsɛvənti]", pos: "num.", cat: "數量與代名詞 🔢", ex: "Grandpa is seventy years old but very strong.", ex_zh: "爺爺雖然已經七十歲了，身體依舊硬朗強壯。" },
  { id: 893, en: "several", zh: "幾個的/數個", kk: "[ˈsɛvrəl]", pos: "adj./pron.", cat: "數量與代名詞 🔢", ex: "I have several storybooks in my school bag.", ex_zh: "我的書包裡帶了好幾本精彩的故事書。" },
  { id: 894, en: "shake", zh: "搖動/握手", kk: "[ʃek]", pos: "v.", cat: "動作與活動 🏃", ex: "Shake hands politely when you meet new friends.", ex_zh: "認識新朋友時禮貌地握手致意。" },
  { id: 895, en: "shall", zh: "將/應該", kk: "[ʃæl]", pos: "aux.", cat: "日常表達 💬", ex: "Shall we go to the playground together?", ex_zh: "我們一起手牽手到操場去玩，好嗎？" },
  { id: 896, en: "shape", zh: "形狀", kk: "[ʃep]", pos: "n.", cat: "色彩與形狀 🎨", ex: "Circles and squares are common geometric shapes.", ex_zh: "圓形和正方形是日常生活中常見的幾何圖形。" },
  { id: 897, en: "share", zh: "分享", kk: "[ʃɛr]", pos: "v.", cat: "能力與特質 🌟", ex: "Good friends share their joy and snacks.", ex_zh: "好朋友會主動分享他們的快樂與好吃的點心。" },
  { id: 898, en: "shark", zh: "鯊魚", kk: "[ʃɑrk]", pos: "n.", cat: "動物與自然 🐶", ex: "Sharks swim fast and have sharp teeth.", ex_zh: "鯊魚游泳速度極快，並且長著銳利的牙齒。" },
  { id: 899, en: "she", zh: "她", kk: "[ʃi]", pos: "pron.", cat: "數量與代名詞 🔢", ex: "She is a kind and thoughtful classmate.", ex_zh: "她是個心地善良又處處為人著想的好同學。" },
  { id: 900, en: "sheep", zh: "綿羊", kk: "[ʃip]", pos: "n.", cat: "動物與自然 🐶", ex: "Fluffy white sheep eat green grass on the farm.", ex_zh: "毛茸茸的白色綿羊在農場上安靜地吃青草。" }
